@dataclass(kw_only=True)
class QueryProbeArgs(Command):
    "A field value at a point (default: the last solved Step). Nodal fields are\ninterpolated; errorEstimate returns the containing element's constant value\nwith interpolated=false. Shared-face ties use the lowest element id. Component\nindices: displacement 0..3, stress Voigt 0..6 (xx, yy, zz, xy, xz, yz), principal 0..3.\nOptional sample selects a retained primary-field frame; omitted means the final field.\nOmitted resultId refuses `result.stale` after edits; an explicit id uses its solved Mesh."
    _tag = "query"
    _name = "query.probe"
    result_id: Any = OMIT
    step: Any = OMIT
    field: Any
    component: Any = OMIT
    sample: Any = OMIT
    at: Any
    _keys = {"result_id":"resultId","step":"step","field":"field","component":"component","sample":"sample","at":"at"}

@dataclass(kw_only=True)
class QueryPathArgs(Command):
    "A field sampled at `n` points along the line from `from` to `to`, for a line plot.\nOptional sample selects a retained primary-field frame; omitted means the final field.\nOmitted resultId refuses `result.stale` after edits; an explicit id uses its solved Mesh."
    _tag = "query"
    _name = "query.path"
    result_id: Any = OMIT
    step: Any = OMIT
    field: Any
    component: Any = OMIT
    sample: Any = OMIT
    from_: Any
    to: Any
    n: int
    _keys = {"result_id":"resultId","step":"step","field":"field","component":"component","sample":"sample","from_":"from","to":"to","n":"n"}

@dataclass(kw_only=True)
class QueryCostArgs(Command):
    "Cost before solving: DOF, matrix non-zero bounds, exact retained-frame schedule and\ncounted peak memory. Counting uses at most 16 MiB scratch after meshing. Feasibility is\nfalse above a fixed 1.5 GiB planning budget, otherwise unknown because solver fill,\nallocator overhead and host serialization are excluded.\nUse before large solves; this query does not promise that a solve fits the current host."
    _tag = "query"
    _name = "query.cost"
    step: str
    _keys = {"step":"step"}

@dataclass(kw_only=True)
class QueryJournalArgs(Command):
    "The Journal: every applied Command with the Model hash after it, and whether undo or\nredo is possible. `fromSeq` returns only entries at or after that sequence number."
    _tag = "query"
    _name = "query.journal"
    from_seq: Any = OMIT
    _keys = {"from_seq":"fromSeq"}

@dataclass(kw_only=True)
class QueryJournalDiffArgs(Command):
    "Compare this Model's Journal with a supplied base Journal. Returns the shared causal\nprefix and each ordered divergent tail: removed entries belong to `base`, added entries\nto the current Journal. Entry identity is the typed Command plus `hashAfter`; `seq` is\nonly a displayed location and is ignored. Entries after the first divergence are not\nre-aligned. This read never replays either Journal."
    _tag = "query"
    _name = "query.journalDiff"
    base: Any
    _keys = {"base":"base"}

@dataclass(kw_only=True)
class QueryScriptArgs(Command):
    "The Journal as a TypeScript script against the `fem` API that reproduces the Model line by\nline; what the Script panel shows and what script.run accepts back."
    _tag = "query"
    _name = "query.script"
    _keys = {}

@dataclass(kw_only=True)
class QueryConvertArgs(Command):
    "Convert a quantity to another unit of the same dimension (\"2 MPa\" to \"psi\"); an error\nnames the dimensions when they differ. Handy for checking inputs before using them.\nRejects nonfinite values and nonzero scaling that rounds to zero, including input\nscaling before adding a temperature offset. Surviving subnormals, ordinary f64\nrounding and affine zeros (273.15 K to 0 degC) remain valid."
    _tag = "query"
    _name = "query.convert"
    quantity: Any
    to: str
    _keys = {"quantity":"quantity","to":"to"}

@dataclass(kw_only=True)
class QueryAbaqusDependenciesArgs(Command):
    "Inspect the supplied Abaqus bundle for missing INCLUDE and NODE/ELEMENT INPUT files.\nUses the same bounded lexer and safe relative-path graph as conversion. This read\nperforms no model/physics conversion or file/network I/O; hosts can acquire listed\nfiles through their captured scoped I/O and repeat until the bundle is complete.\nThe actual conversion still rejects missing files and never publishes partial data."
    _tag = "query"
    _name = "query.abaqusDependencies"
    text: str
    source_name: Any = OMIT
    source_files: Any = OMIT
    _keys = {"text":"text","source_name":"sourceName","source_files":"sourceFiles"}

@dataclass(kw_only=True)
class QueryConvertAbaqusArgs(Command):
    "Convert a bounded Abaqus text deck to checked portable Commands without mutating\nthe active Model or solving. Explicit positive unitLength and static-mode unitForce\ndefine source units; coordinates/displacements scale by L, forces by F and stress\nby F/L². Structural instances, labels, exact Sets and surfaces are normalized by\nthe typed deck reader. The report records all translated analysis Steps and notes\nrecognized requests whose output/increment execution differs from FEM Lab.\nStatic mode imports constant isotropic materials and exact nonoverlapping solid\nsection regions covering every element, direct or solid symbolic BOUNDARY,\nCLOAD and uniform DLOAD Pn / DSLOAD P pressure. Multiple small-displacement static\nSteps retain effective inherited loads/supports; OP=NEW resets that family's state,\nOP=MOD updates it. Conflicting repeated definitions within one Step fail explicitly.\nEach Step configures its final linear equilibrium, without source increment history.\nUnsupported physics/formulations/parameters fail rather than being discarded.\nMesh mode configures no analysis. Neither mode infers missing physical units.\nInput and serialized response are bounded to 16 MiB; hosts must privately prepare\nall returned Commands through Candidate and publish one validated replacement."
    _tag = "query"
    _name = "query.convertAbaqus"
    text: str
    name: str
    body: str
    mode: Any
    unit_length: Any
    unit_force: Any = OMIT
    unit_time: Any = OMIT
    source_name: Any = OMIT
    source_files: Any = OMIT
    sha256: str
    _keys = {"text":"text","name":"name","body":"body","mode":"mode","unit_length":"unitLength","unit_force":"unitForce","unit_time":"unitTime","source_name":"sourceName","source_files":"sourceFiles","sha256":"sha256"}

@dataclass(kw_only=True)
class QueryMaterialLibraryArgs(Command):
    "Primary-source material data with dimensions, grade, condition, temperature and a source\nfor every reported property. With no `name`, lists the stable catalogue. With a canonical\nid, name or unambiguous alias, returns that entry. Missing properties are explicit nulls:\nnever infer them before material.add. Copy the entry's `materialAddSource` into that\nCommand's `source` so the Journal preserves provenance."
    _tag = "query"
    _name = "query.materialLibrary"
    name: Any = OMIT
    _keys = {"name":"name"}

@dataclass(kw_only=True)
class QueryObjectsArgs(Command):
    "Every nameable thing in the Model as `@`-mention references (`body:beam`, `set:beam.top`,\n`material:steel`, `journal:12`), with a one-line summary each; the mention picker's index."
    _tag = "query"
    _name = "query.objects"
    kinds: Any = OMIT
    _keys = {"kinds":"kinds"}

@dataclass(kw_only=True)
class QueryReportArgs(Command):
    "The whole analysis as one Markdown calculation note: assumptions, geometry, materials,\nmesh and quality, loads with totals, results with the reaction balance, the verification\nchecks with a hand calculation where one applies, and the Journal as an appendix. Nothing\nin it depends on the clock or the machine, so two runs of the same Journal produce\nbyte-identical text. `step` reports one Step instead of every solved one; `include` picks\nsections. Automatic hand references require a current static Step on an uncut 3D lattice\nbox with one fully clamped end and one single-component force on the opposite end;\nother cases explicitly report no applicable automatic reference. Formulas are `$$…$$` for KaTeX."
    _tag = "query"
    _name = "query.report"
    step: Any = OMIT
    include: Any = OMIT
    _keys = {"step":"step","include":"include"}

@dataclass(kw_only=True)
class QueryCapabilitiesArgs(Command):
    "What this engine can do here: GPU presence and adapter name, thread count, engine and\nschema versions. Hosts add browser facts (cross-origin isolation, local or remote engine)."
    _tag = "query"
    _name = "query.capabilities"
    _keys = {}

class API:
    _call: Any
    def model_new(self, *, name: str, description: Any = OMIT) -> Any:
        "Start a new, empty Model and Journal with this name. Discards the current Model, its\nResults and the undo history; it is the first entry of every Journal, so call it once\nat the start, never to \"reset\" mid-way (use journal.undo for that)."
        return self._call("dispatch", ModelNewArgs(name=name, description=description).wire())

    def model_set_units(self, *, units: Any) -> Any:
        "Choose the display units used by Queries and the UI (for example mm, kN, MPa, kW). Storage\nstays SI and every input may still use any unit of the right dimension; this only\nchanges how values are reported back. A scalar that cannot fit in the selected unit\nproduces `unit.display` when queried or reported, without altering its stored SI data.\nChoose larger or SI display units to read it; formatting never silently changes units."
        return self._call("dispatch", ModelSetUnitsArgs(units=units).wire())

    def model_set_name(self, *, name: str) -> Any:
        "Change the Model's display name without resetting geometry, history or solved Results.\nA name-only edit is undoable and changes the full Model/Journal identity, but does not\nchange the Result-validity fingerprint. Whitespace-only names are rejected."
        return self._call("dispatch", ModelSetNameArgs(name=name).wire())

    def model_set_idealisation(self, *, idealisation: Any) -> Any:
        "Set the idealisation: 3D solids (default), plane stress with a thickness, plane strain,\nor axisymmetric (x = radius, y = axis). 2D idealisations need Sheet bodies and 3D needs\nsolid bodies; mixing them makes the Model ill-posed."
        return self._call("dispatch", ModelSetIdealisationArgs(idealisation=idealisation).wire())

    def model_rename(self, *, kind: Any, name: str, to: str) -> Any:
        "Rename a Body, Material, Set, Constraint, Load or Step and every reference to it. A Body\nrename also renames its auto faces (`<name>.xmin` …). Fails with name.taken if `to`\nalready exists in that kind. Bodies and Sets also share the geometry namespace with\ncuts and point masses, so their new name cannot shadow any geometry owner.\nMapped and swept mapped Bodies also rename their mesher\ngeometry, named Face/Body-region selectors and material association."
        return self._call("dispatch", ModelRenameArgs(kind=kind, name=name, to=to).wire())

    def model_duplicate(self, *, kind: Any, name: str, as_: str) -> Any:
        "Copy an object under a new name. A Body copy shares nothing with the original; a Step\ncopy references the same Constraints and Loads. Useful for \"the same load case but\ntwice the pressure\": duplicate, then re-issue the create Command with the new value.\nA mapped or swept mapped Body cannot be copied: the Model has one mesher geometry\nslot. Returns unsupported without changing the Model; use model.rename or mesh.set.\nA Body or Set copy cannot reuse a Body, cut, named Set or point-mass name."
        return self._call("dispatch", ModelDuplicateArgs(kind=kind, name=name, as_=as_).wire())

    def geometry_add_box(self, *, name: str, size: Any, at: Any = OMIT) -> Any:
        "Add an axis-aligned box Body with its minimum corner at `at` (default the origin). Its\nsix faces are auto-named `<name>.xmin`, `<name>.xmax`, … `<name>.zmax` and can be used\ndirectly in constraints and loads. Re-issuing with an existing name replaces the Body\nwhile preserving its material, section and cuts; incompatible or consuming cuts reject\nthe replacement without changing the Model."
        return self._call("dispatch", GeometryAddBoxArgs(name=name, size=size, at=at).wire())

    def geometry_subtract_box(self, *, name: str, from_: str, size: Any, at: Any) -> Any:
        "Cut an axis-aligned box out of the Body `from` (a hole, notch or opening). The cut's\nwalls are auto-named `<name>.xmin` … and refer to the faces of the hole, so a pressure\non `hole.zmin` acts on the hole's floor. Cuts that remove everything are an error.\nMapped and swept mapped Bodies return unsupported; edit their blocks with mesh.set."
        return self._call("dispatch", GeometrySubtractBoxArgs(name=name, from_=from_, size=size, at=at).wire())

    def geometry_add(self, *, name: str, shape: Any) -> Any:
        "Add a Body from any shape: box, cylinder, sphere, an extruded or revolved sketch, a\n2D sheet, or booleans of those. Faces are auto-named `<name>.<tag>` from the shape\n(`side`, `top`, sketch segment tags, …); list them with query.model. Lengths need units.\nReplacing an existing Body preserves its material, section and cuts, and validates the\nresulting shape before changing the Model."
        return self._call("dispatch", GeometryAddArgs(name=name, shape=shape).wire())

    def geometry_add_line(self, *, name: str, points: Any, members: Any = OMIT, divisions: Any = OMIT, kind: Any = OMIT) -> Any:
        "Add a Body made of straight line members: a truss or a frame. `points` are the joints,\nin order, and `members` are index pairs into them; the default is a chain 0-1, 1-2, and\nso on. Each member is cut into `divisions` elements of equal length (default 1). Joint\n`i` becomes the node Set `<name>.p<i>`, which is what a constraint or a nodal force\ntargets, and joints of different line Bodies that sit at the same point are welded into\none node when the Mesh is built. `kind` is `truss` (the default: pin-jointed bars that\ncarry axial force only, so hold enough joints that none can drift sideways — an\nunder-braced truss is singular and fails in the solver, not here) or `beam` (Timoshenko\nbeams carrying axial force, shear, bending and torsion; every joint then has three\nrotations rx, ry, rz as well as ux, uy, uz, so constraint.fix clamps it and\nconstraint.pin pins it, and load.moment can act on it). Either way give the Body a\nSection with section.assign as well as a Material. Line Bodies need the 3D\nidealisation and are not cut, meshed or previewed as solids. Replacing a Body that has\ncuts therefore fails without changing the Model."
        return self._call("dispatch", GeometryAddLineArgs(name=name, points=points, members=members, divisions=divisions, kind=kind).wire())

    def geometry_subtract(self, *, name: str, from_: str, shape: Any) -> Any:
        "Cut a shape out of the Body `from`. The cut's faces are auto-named `<name>.<tag>` (for a\ncylinder: `<name>.side`), which is how you load or fix the wall of a hole. The shape\nis positioned in world coordinates, so use its `at` or a transform to place it.\nMapped and swept mapped Bodies return unsupported; edit their blocks with mesh.set."
        return self._call("dispatch", GeometrySubtractArgs(name=name, from_=from_, shape=shape).wire())

    def geometry_import(self, *, name: str, format: Any, data: str, encoding: Any = OMIT, sha256: Any = OMIT, unit_length: Any, feature_angle: Any = OMIT, simplify_below: Any = OMIT) -> Any:
        "Import a triangle-mesh geometry file as a Body: the file travels *inside* the Command\nas `data`, so a Journal replays with no external file, no network and no file system,\non any host. STL carries no units, so `unitLength` says what one file unit is (`1 mm`\nfor a part drawn in millimetres). The mesh is welded into a watertight solid, so\nvolume, mass, booleans and meshing all work on it; its faces are patches of triangles\nthat meet more smoothly than `featureAngle` (30 degrees by default), auto-named\n`<name>.face0`, `<name>.face1`, ... largest area first. Those numbers move when the\nfile changes, so for anything you will re-import, name the faces you need with\ngeometry.nameFace predicates (a plane, a cylinder): those are re-resolved at every\nremesh and survive a re-import. `simplifyBelow` collapses features smaller than the\ngiven length, which is the honest half of defeaturing; there is no fillet, chamfer or\nshell. Re-import preserves the Body's material, section and cuts, and validates the\nresulting shape before changing the Model. Give `sha256` to have the engine verify the\ndata is the file you meant."
        return self._call("dispatch", GeometryImportArgs(name=name, format=format, data=data, encoding=encoding, sha256=sha256, unit_length=unit_length, feature_angle=feature_angle, simplify_below=simplify_below).wire())

    def geometry_name_face(self, *, name: str, of: str, where: Any) -> Any:
        "Name a face Set of Body `of` by a geometric rule (plane, normal, box, cylinder, or any\nof those) so constraints and loads can target it. Rules are re-evaluated after every\nremesh, so the Set survives refinement. Body `of` may be explicit geometry or the\nimplicit Body defined by a mapped or swept mapped mesher. The rule selects only that\nBody's actual mesh boundary. Prefer the auto face names when one fits.\nReissuing replaces an existing named Set; a Body, cut or point-mass name is reserved."
        return self._call("dispatch", GeometryNameFaceArgs(name=name, of=of, where=where).wire())

    def geometry_name_region(self, *, name: str, where: Any) -> Any:
        "Name a node/element Set by a region rule (a box or a whole Body), for point-like\nconstraints, nodal forces and probes. Node sets from regions are exact at mesh nodes;\nuse a box slightly larger than the points you mean. A whole-Body rule also accepts\nthe implicit Body defined by a mapped or swept mapped mesher.\nReissuing replaces an existing named Set; a Body, cut or point-mass name is reserved."
        return self._call("dispatch", GeometryNameRegionArgs(name=name, where=where).wire())

    def geometry_remove(self, *, name: str) -> Any:
        "Remove a Body, a cut, a named Set or a point mass from their shared geometry namespace.\nFails with in-use listing the constraints, loads\n(including temperature and volumetric heat sources), named selectors or free-mesher\ngeometry references that still use a Body; remove or retarget those first. Removing\na mapped or swept mapped Body clears its mesher and material association, preserving\nunrelated explicit geometry and Materials."
        return self._call("dispatch", GeometryRemoveArgs(name=name).wire())

    def geometry_add_mass(self, *, name: str, at: Any, mass: Any) -> Any:
        "Add a lumped point mass at a coordinate: one node of its own, carrying mass and nothing\nelse. It contributes to the mass matrix (so it changes modal frequencies) and to gravity\n(m·g at that point), and has no stiffness whatever, so it must be attached to the model\nwith constraint.couple: on its own it makes the Model ill-posed and solve.run refuses.\nThe point is also a node Set of the same name, so constraint.couple, constraint.fix,\nload.force and query.set target it by name. Re-issuing an existing point-mass name\nreplaces it; other Body, cut and named-Set names are reserved. geometry.remove deletes\nit. It carries no rotary inertia — a node has no rotations —\nso it models a compact mass, not a flywheel."
        return self._call("dispatch", GeometryAddMassArgs(name=name, at=at, mass=mass).wire())

    def material_add(self, *, name: str, E: Any = OMIT, nu: Any = OMIT, orthotropic: Any = OMIT, orientation: Any = OMIT, rho: Any = OMIT, alpha: Any = OMIT, k: Any = OMIT, cp: Any = OMIT, yield_: Any = OMIT, plasticity: Any = OMIT, source: Any = OMIT) -> Any:
        "Define a Material: elastic stiffness is either isotropic, by Young's modulus `E` and\nPoisson's ratio `nu` (0 ≤ ν < 0.5), or orthotropic, by the `orthotropic` block — never\nboth. A heat-only Material omits both stiffness forms and gives positive conductivity\n`k`; `rho` and `cp`, when stated, must also be positive and are required by heat-transient.\nHeat-only Materials may retain `alpha` and `yield` for later structural use; `plasticity`\nrequires isotropic stiffness, and mechanical Steps require elastic stiffness.\n`orientation` turns the material axes (wood grain, fibre direction, rolling\ndirection) away from the global axes; without it they are the global axes. Density `rho`\nis needed for gravity and modal analysis, `alpha` for thermal loads, `k` and `cp` for\nheat transfer; `source` records where the numbers came from. `yield` is the yield\nstress the safety factor and the `plasticity` block read; `plasticity` makes the\nmaterial elastic–plastic (J2, isotropic hardening) in `static-nonlinear` Steps. Re-issuing\nwith an existing name edits the material in place, so an omitted `orientation` or\n`plasticity` clears the previous one."
        return self._call("dispatch", MaterialAddArgs(name=name, E=E, nu=nu, orthotropic=orthotropic, orientation=orientation, rho=rho, alpha=alpha, k=k, cp=cp, yield_=yield_, plasticity=plasticity, source=source).wire())

    def material_assign(self, *, material: str, bodies: Any) -> Any:
        "Assign a Material to one or more Bodies. Imported element regions are editable Bodies;\nassigning the source owner supplies their default, while region assignments override it.\nEvery element-owning Body needs a Material before solving; a missing assignment is\nreported by query.model and blocks solve.run."
        return self._call("dispatch", MaterialAssignArgs(material=material, bodies=bodies).wire())

    def material_remove(self, *, name: str) -> Any:
        "Remove a Material that is not assigned to any Body. Fails with in-use listing the Bodies\nthat still use it; assign them another Material first with material.assign."
        return self._call("dispatch", MaterialRemoveArgs(name=name).wire())

    def section_add(self, *, name: str, shape: Any) -> Any:
        "Define a section: homogeneous shell thickness, a bottom-to-top laminate stack\nof 1–256 plies with named Materials and unit-bearing angles, or a line Body cross-section\n(`geometry.addLine`): rectangle, circle, tube, I, channel, or properties given directly. A line member has no cross-section\ngeometry of its own, so the Section is where its area, second moments, torsion constant,\nshear factors and extreme-fibre distances come from. Re-issuing with an existing name\nedits the section in place. Assign it to Bodies with section.assign."
        return self._call("dispatch", SectionAddArgs(name=name, shape=shape).wire())

    def section_assign(self, *, section: str, bodies: Any, orientation: Any = OMIT) -> Any:
        "Assign a Section to one or more Bodies, including imported element regions. A region\noverrides the source owner Section; an unassigned region inherits that default.\nEvery line or shell Body needs a Section before solving;\none without it is reported by query.model warnings and blocks solve.run with\nmodel.no-section. A shell needs a shell thickness section, a line member needs a\ncross-section, and a solid gets its section from its geometry. `orientation` names the global\naxis the section's local z (its `height` direction, the one `iY` resists bending along)\nfollows for the beams of these Bodies: local z is that axis made perpendicular to each\nmember, and local y completes the right-handed triad (y = z × x). It may not lie along\na member. Without it the rule is: local z follows global Z, so a horizontal beam has\nits height vertical; a member within 1e-6 of vertical follows global X instead, so a\ncolumn's local z points along +X. `iZ` then resists bending along local y. Trusses\nignore it. For laminate shells, orientation instead selects the tangent projection\nof that global axis as the zero-angle ply direction. A normal axis is rejected.\nWithout it ply angles use the midsurface's first parametric direction."
        return self._call("dispatch", SectionAssignArgs(section=section, bodies=bodies, orientation=orientation).wire())

    def section_remove(self, *, name: str) -> Any:
        "Remove a Section that is not assigned to any Body. Fails with in-use listing the Bodies\nthat still use it; assign them another Section first with section.assign."
        return self._call("dispatch", SectionRemoveArgs(name=name).wire())

    def mesh_set(self, *, mesher: Any, order: Any = OMIT, formulation: Any = OMIT, simplices: Any = OMIT, refinement: Any = OMIT) -> Any:
        "Choose the Mesher and element settings; the Mesh is rebuilt lazily when needed. `order`\n1 gives linear elements, 2 quadratic (more accurate in bending and at stress peaks).\n`formulation: mean-dilatation` gives small-strain Hex8 the volume-averaged B-bar\nstrain used by Abaqus C3D8; other kinds keep full integration. Existing full Journals\nretain their original pointwise strain. Mean-dilatation Hex8 cannot run finite deformation.\n`formulation: full` is the textbook linear element that locks in bending: keep the\ndefault incompatible modes or use order 2 when bending matters. Mesher-defined geometry\nowns a Body name distinct from explicit Bodies, cuts, named Sets and point masses.\nKeeping that name preserves its material;\nchanging/removing it requires no remaining Body references and clears its material.\nUse model.rename to change an implicit Body name while preserving its references.\n`simplices: true` splits hexes into tetrahedra (tet4/tet10) and quads into triangles\n(tri3/tri6), preserving named faces. It does not make a free tetrahedral mesh of curved\ngeometry: the selected mesher still determines the boundary approximation, and the `tet`\nmesher is the one that meshes a curved solid freely. `formulation` has no effect when\n`simplices` is true, or under the `tet` mesher, because simplex elements have no\nincompatible modes. Imported sources retain authored labels/connectivity and exact Sets,\ndefault to full integration, and require solid3d, no simplex split/refinement.\nTheir element kinds determine interpolation; order 1 means retain the authored source, including quadratic nodes.\nRemoving or emptying a referenced imported Set fails without mutation."
        return self._call("dispatch", MeshSetArgs(mesher=mesher, order=order, formulation=formulation, simplices=simplices, refinement=refinement).wire())

    def mesh_export(self, *, format: Any, step: Any = OMIT) -> Any:
        "Write the current Mesh out as text the host saves; the Mesh is built first if it is\nstale. `vtu` is the VTK XML UnstructuredGrid that ParaView opens, carrying the element\nid and the Body index as cell data. Name a `step` to add that Step's result fields as\npoint data — displacement, reaction, stress and von Mises — so ParaView colours by them.\nResult fields require the Model state they were solved on; `result.stale` means run\n`solve.run` on that Step again before exporting it with the current Mesh.\n`msh`, `inp` and `stl` write the Mesh alone (Gmsh, Abaqus/CalculiX, an STL skin).\n`inp` preserves exact Set labels with Abaqus quoting; an unsupported label or heading\nreturns `export.unavailable`. It writes no Materials, Constraints, Loads or Steps."
        return self._call("dispatch", MeshExportArgs(format=format, step=step).wire())

    def constraint_fix(self, *, name: str, on: str, dofs: Any = OMIT) -> Any:
        "Fix degrees of freedom to zero on a Set (default: all displacement components, a\nclamped support). A fix that holds all three displacements and names no rotation is a\nclamp: on a beam joint it holds the three rotations rx, ry, rz as well, so a beam's\nfixed end is what `constraint.fix` without `dofs` means. For a pinned beam support use\nconstraint.pin; for a roller give only the normal component; name rx, ry or rz to hold\na rotation on its own. Rotations are inert on every node that is not a beam joint.\nFixing every node of a Body makes the solve trivial; fix faces, not bodies."
        return self._call("dispatch", ConstraintFixArgs(name=name, on=on, dofs=dofs).wire())

    def constraint_pin(self, *, name: str, on: str) -> Any:
        "Pin a Set: fix its three displacements and leave every rotation free. On a beam joint\nthis is the pinned support of a simply supported beam or a portal frame's base hinge;\nthe only difference from constraint.fix is the rotational restraint. On a solid's\nnodes it is the same as constraint.fix, because those carry no rotation."
        return self._call("dispatch", ConstraintPinArgs(name=name, on=on).wire())

    def constraint_prescribe(self, *, name: str, on: str, dof: Any, value: Any) -> Any:
        "Prescribe a non-zero displacement of one component on a Set, for example a settlement\nof \"2 mm\" in uy. Reactions on prescribed Sets are reported like any other constraint."
        return self._call("dispatch", ConstraintPrescribeArgs(name=name, on=on, dof=dof, value=value).wire())

    def constraint_symmetry(self, *, name: str, on: str, normal: Any) -> Any:
        "Symmetry plane: fixes the displacement component along `normal` on the Set (the cut\nface of a half or quarter model), and on beam joints the two rotations about the axes\nin the plane. Model a half and say so in the report; loads on the symmetry plane\nitself must be halved by you."
        return self._call("dispatch", ConstraintSymmetryArgs(name=name, on=on, normal=normal).wire())

    def constraint_temperature(self, *, name: str, on: str, value: Any) -> Any:
        "Hold a Set at a fixed temperature in a heat Step (the Dirichlet boundary of conduction).\nA heat Step needs either one of these or a convection boundary, or the temperature is\nonly defined up to a constant and the solve is singular. In a transient Step the value is\nmultiplied by the Step's `amplitude`, so \"100 K\" with a sine amplitude is a driven end."
        return self._call("dispatch", ConstraintTemperatureArgs(name=name, on=on, value=value).wire())

    def contact_add(self, *, name: str, master: str, slave: str, kind: Any, tol: Any = OMIT) -> Any:
        "Connect two face Sets. `bonded` ties them so the parts behave as one: every node of\n`slave` is constrained to the point it projects onto in `master`, in every displacement\ncomponent. It is a linear constraint inside the same operator — no iteration, no gap\nopening, no sliding — so a bonded assembly costs a static solve, not a contact search.\n`tol` is then the largest gap that still pairs, defaulting to 1e-4 of the Mesh diagonal;\na node further from the master than that is `contact.unpaired`. In a heat Step a bonded\ntie carries temperature, so the two parts are in perfect thermal contact.\n`frictionless` lets the faces press, open and slide: `tol` is then the *search distance*\n(same default), every slave node within it is paired and its initial gap along the master\nnormal recorded (positive when open, so faces may start apart and close under load), and\nthe solve keeps a node on the master surface only while the normal force there is\ncompressive. A node beyond `tol` is simply not a candidate. Hold each Body against the\nmotions the contact cannot stop: a frictionless face transmits no tangential force, so a\npart held only by it can still slide. The Result carries a `contactPressure` field on the\nslave nodes and query.result lists every frictionless pair with its active fraction and\nthe resultant it carries; a pair that ends fully open is a `contact.open` warning, a part\nthat lifts off entirely with nothing else holding it a `contact.open` error, and a set\nthat never settles a `contact.chatter` error naming the nodes. Put the *finer* mesh on\nthe slave side either way: a node-to-face constraint passes the patch test that way\nround. A contact is listed in a Step's `constraints` like any other, and is removed with\nconstraint.remove. Contacts add stiffness between Bodies that share no element, which\nquery.cost does not count."
        return self._call("dispatch", ContactAddArgs(name=name, master=master, slave=slave, kind=kind, tol=tol).wire())

    def constraint_cyclic(self, *, name: str, from_: str, to: str, axis: Any, angle_deg: float, through: Any = OMIT, tol: Any = OMIT) -> Any:
        "Tie two sector faces related by a rotation: u(to) = R·u(from), with R the rotation of\n`angleDeg` about `axis` through `through` (default the origin). This is the zero-harmonic\ncondition: a static solve is exact for loading that repeats sector by sector, and a modal\nStep finds only the harmonic-index-0 family. Non-zero harmonics need a complex\neigenproblem and are not implemented. The two faces must mesh identically — use the\nrevolve mesher, whose `<body>.theta0` and `<body>.theta1` Sets are what this Command is\nfor. The tie is node to node, not node to face, because a matching sector mesh is the\nonly case in scope. Because the coefficients are a rotation rather than a partition of\nunity, a cyclic model's global reaction sum is not the applied load — read\nquery.result's per-Constraint reactions, never its balance, on a Step that lists this\nCommand. Refused in an explicit Step, like a bonded contact."
        return self._call("dispatch", ConstraintCyclicArgs(name=name, from_=from_, to=to, axis=axis, angle_deg=angle_deg, through=through, tol=tol).wire())

    def constraint_couple(self, *, name: str, point: str, on: str, kind: Any) -> Any:
        "Connect a point mass (geometry.addMass) to a face Set, the way a bolt, a bearing or a\nload introduction is idealised. `distributed` makes the point follow the face's weighted\nmean displacement and adds no stiffness at all, so a force at the point spreads over the\nface in exactly the weights a uniform traction would produce, and a mass at the point\nloads the face the same way; that is the one to reach for. `rigid` is the opposite:\nevery node of the face takes the point's displacement, so the face cannot deform and the\npart around it is stiffer than the real one. Nodes carry translations only, so **neither\nkind transmits a moment**: a couple cannot be applied at the point, and a rigid coupling\ndoes not rotate its face — it translates it. It is a linear multipoint constraint inside\nthe same operator, needs no iteration, is listed in a Step's `constraints` like any\nother Constraint, and is removed with constraint.remove."
        return self._call("dispatch", ConstraintCoupleArgs(name=name, point=point, on=on, kind=kind).wire())

    def constraint_remove(self, *, name: str) -> Any:
        "Remove a Constraint. Fails with in-use if a Step still lists it; re-issue step.add without\nit first. Removing a constraint makes existing Results of that Step stale."
        return self._call("dispatch", ConstraintRemoveArgs(name=name).wire())

    def load_pressure(self, *, name: str, on: str, value: Any) -> Any:
        "Uniform pressure on a face Set, positive into the surface (a negative value pulls).\nPressure times query.set.pressureArea is a scalar integral; it is not the net vector\nforce on a curved Set. The loaded area includes thickness or axisymmetric weighting.\nShell pressureArea measures the original midsurface; physical curved shell face loads\ninclude the Section's top/bottom offsets."
        return self._call("dispatch", LoadPressureArgs(name=name, on=on, value=value).wire())

    def load_traction(self, *, name: str, on: str, total: Any) -> Any:
        "A total force vector spread uniformly over a face Set's area (\"10 kN downward on this\nface\"). Use this instead of nodal forces on solids: point loads give singular stresses."
        return self._call("dispatch", LoadTractionArgs(name=name, on=on, total=total).wire())

    def load_force(self, *, name: str, on: str, total: Any) -> Any:
        "A total force split equally over the nodes of a node Set. Point loads on solids give\nsingular stresses near the node; prefer load.traction on a face unless you mean a point."
        return self._call("dispatch", LoadForceArgs(name=name, on=on, total=total).wire())

    def load_moment(self, *, name: str, on: str, total: Any) -> Any:
        "A concentrated moment, as a total vector about the global axes, split equally over the\nnodes of a node Set. It acts on the rotational degrees of freedom, which only the\njoints of beam Bodies have: on any other node it has nothing to act on and the Step\nfails with model.ill-posed naming the Load. Right-handed about each axis, in the\nModel's torque unit (\"5 kN m\")."
        return self._call("dispatch", LoadMomentArgs(name=name, on=on, total=total).wire())

    def load_gravity(self, *, name: str, g: Any) -> Any:
        "Gravity (or any uniform acceleration) as a body force on every Body whose Material has\na density; Bodies without one are skipped and listed in the warnings. Explicit Steps\napply gravity with their lumped inertia (m_i g); static Steps use consistent body forces."
        return self._call("dispatch", LoadGravityArgs(name=name, g=g).wire())

    def load_temperature(self, *, name: str, bodies: Any, value: Any, reference: Any = OMIT) -> Any:
        "A uniform temperature on the listed Bodies relative to `reference` (default 293.15 K),\nproducing thermal strain α·ΔT in a static Step. Needs `alpha` on the Material.\nTargets may be explicit geometry or the Body defined by a mapped or swept mapped mesher.\nDisjoint Bodies compose independently, each using its own reference. Overlapping\nassignments must produce exactly the same increment; otherwise `solve.run` returns\n`model.ill-posed` naming both Loads and the Body. Equal increments are not added.\nWhen continuing a heat Step, its nodal temperatures replace `value`; these per-Body\nreferences still apply, with 293.15 K on Bodies without a temperature Load."
        return self._call("dispatch", LoadTemperatureArgs(name=name, bodies=bodies, value=value, reference=reference).wire())

    def load_convection(self, *, name: str, on: str, h: Any, t_inf: Any) -> Any:
        "Newton cooling on a face Set: heat `h (T − tInf)` leaves the surface per unit area. This\nis the usual \"exposed to air\" boundary and, unlike a flux, it also stiffens the system,\nso a heat Step with a convection face needs no fixed temperature to be well posed."
        return self._call("dispatch", LoadConvectionArgs(name=name, on=on, h=h, t_inf=t_inf).wire())

    def load_heat_flux(self, *, name: str, on: str, q: Any) -> Any:
        "A prescribed heat flux into a face Set, in W/m² (negative flows outward). An insulated\nface needs no Command at all: zero flux is what a face with no boundary condition does."
        return self._call("dispatch", LoadHeatFluxArgs(name=name, on=on, q=q).wire())

    def load_radiation(self, *, name: str, on: str, emissivity: float, t_inf: Any) -> Any:
        "Grey-body radiation from a face Set to a large surrounding at `tInf`: the surface loses\n`sigma * emissivity * (T^4 - tInf^4)` per unit area, with the Stefan-Boltzmann constant\nsigma = 5.670374419e-8 W/(m^2 K^4) built in. Both temperatures are absolute, so a Model\ndisplayed in degC is converted to kelvin before the fourth power is taken. `emissivity`\nis dimensionless and must lie in (0, 1]; 1 is a black body. Like a convection face this\nholds the temperature, so a heat Step whose only boundary is radiation is still well\nposed. Radiation makes a heat Step nonlinear: it is solved by repeated assembly and\nsolution, governed by step.add's nonlinearTolerance and nonlinearMaxIterations. A\nheat-steady Result reports the number of passes as its solver iteration count, and a Step\nthat runs out of them fails with solve.diverged rather than returning a wrong answer."
        return self._call("dispatch", LoadRadiationArgs(name=name, on=on, emissivity=emissivity, t_inf=t_inf).wire())

    def load_heat_source(self, *, name: str, bodies: Any, q: Any) -> Any:
        "A volumetric heat source on whole Bodies, in W/m³ (ohmic heating, hydration, a reaction).\nIt is a density, not a total: the heat delivered is `q` times each Body's volume.\nTargets may be explicit geometry or the Body defined by a mapped or swept mapped mesher;\nfor a plane-stress Sheet, the volume includes its specified thickness."
        return self._call("dispatch", LoadHeatSourceArgs(name=name, bodies=bodies, q=q).wire())

    def load_torque(self, *, name: str, on: str, total: Any) -> Any:
        "A torsional load on a face Set of an axisymmetric Model with twist: a circumferential\ntraction `t_theta = c r` at every Gauss point, with `c` chosen so the net torque about\nthe axis equals `total` exactly, curved faces included. Outside the axisymmetric\nidealisation with twist this is `unsupported`; enable it with model.setIdealisation."
        return self._call("dispatch", LoadTorqueArgs(name=name, on=on, total=total).wire())

    def contact_thermal(self, *, name: str, of: str, conductance: Any) -> Any:
        "A finite conductance across a bonded pair: heat h_c·(T_slave − T_master) crosses the\ninterface per unit area, so the two sides are no longer at the same temperature.\nAssembled into the heat operator exactly as load.convection is, except that it couples\ntwo temperature fields instead of one field to tInf. Naming a contact here replaces its\nperfect thermal tie; the mechanical tie is unaffected."
        return self._call("dispatch", ContactThermalArgs(name=name, of=of, conductance=conductance).wire())

    def load_remove(self, *, name: str) -> Any:
        "Remove a Load. Fails with in-use if a Step still lists it; re-issue step.add without it\nfirst. Removing a load makes existing Results of that Step stale."
        return self._call("dispatch", LoadRemoveArgs(name=name).wire())

    def step_add(self, *, name: str, procedure: Any, constraints: Any, loads: Any, output: Any = OMIT, after: Any = OMIT, n_modes: Any = OMIT, shift: Any = OMIT, dt: Any = OMIT, t_end: Any = OMIT, theta: Any = OMIT, output_every: Any = OMIT, dt_factor: Any = OMIT, amplitude: Any = OMIT, initial: Any = OMIT, alpha: Any = OMIT, rayleigh_alpha: Any = OMIT, rayleigh_beta: Any = OMIT, initial_velocity: Any = OMIT, increments: Any = OMIT, max_cutbacks: Any = OMIT, nonlinear_tolerance: Any = OMIT, nonlinear_max_iterations: Any = OMIT, f_start: Any = OMIT, f_stop: Any = OMIT, points: Any = OMIT, sweep: Any = OMIT, damping_ratio: Any = OMIT, damping_ratios: Any = OMIT, psd: Any = OMIT) -> Any:
        "Define an analysis Step: the procedure, and which Constraints and Loads are active in\nit. `output` lists the fields to compute (default displacement, stress, von Mises and\nreactions). Steps run in the order given by step.reorder, and `after` names an earlier\nStep whose Result this one continues — a static Step after a heat Step picks up its\ntemperature field and turns it into thermal stress, and a modal Step after a static one\npicks up its stress state and becomes a prestressed (stress-stiffened) modal analysis,\nwhich is what a tensioned or preloaded member needs. The remaining fields belong to one\nprocedure each and are ignored by the others. Each field declares `x-procedures` in the\nschema (`*` means common to every procedure), so hosts can present the selected procedure\nwithout discarding values when it changes. The Procedure enum declares material inputs\nand result outputs for humans and AI tools. Field ownership: `nModes` and `shift` to modal, `nModes`\nalone (default 1) to buckling, `dt`,\n`tEnd`, `theta`, `initial`, `amplitude` and `outputEvery` to heat-transient, `tEnd`,\n`dtFactor`, `initialVelocity` and `outputEvery` to explicit, `dt`, `tEnd`, `alpha`,\n`rayleighAlpha`, `rayleighBeta`, `initialVelocity`, `amplitude` and `outputEvery` to\nimplicit, `fStart`, `fStop`, `points`, `sweep`, `dampingRatio`, `dampingRatios`,\n`rayleighAlpha`, `rayleighBeta` and `outputEvery` to harmonic, `amplitude`, `dt`, `tEnd` and\n`outputEvery` to static as well, and `increments`, `maxCutbacks`, `tEnd` and\n`amplitude` to static-nonlinear. An\nimplicit Step integrates `M a + C v + K u = f` by HHT-α with `alpha` in [-1/3, 0]\n(default 0, Newmark average acceleration: second order, unconditionally stable and\nenergy-conserving; -0.05 adds numerical damping of the mesh-frequency ringing) and\nRayleigh damping `C = rayleighAlpha·M + rayleighBeta·K` (both default 0; a modal\ndamping ratio ζ at circular frequency ω is `rayleighAlpha/(2ω) + rayleighBeta·ω/2`).\nIts `amplitude` scales the Loads only and is refused with a non-zero prescribed\ndisplacement; its initial acceleration is solved from the loads at t = 0, so a suddenly\napplied load is exactly that. Its reactions include the inertia and damping forces and\nits applied totals are the d'Alembert force `f - M a - C v`, so the balance closes; the\nscalars `load_total_*` keep the plain load. An `amplitude` on a static Step ramps its Loads and\nprescribed displacements over increments from 0 to `tEnd` (default \"1 s\", with `dt`\ndefaulting to the whole of it, so a table written in step fraction works unchanged) and\nkeeps every `outputEvery`-th increment as a retained frame; a temperature Load is never\nscaled, so its thermal strain is present in full at every increment. Without an\n`amplitude` a static Step is the single solve it has always been and retains nothing.\nA static-nonlinear Step always steps, over `increments` equal pieces of the same\npseudo-time, and keeps every converged one.\nHeat-steady requires a finite positive material conductivity `k`; heat-transient also\nrequires finite positive `rho` and `cp`, and its `theta` must lie in [0, 1].\n`query.model` checks each Step's active Constraints/Loads and assigned Materials:\nstatic, static-nonlinear and buckling need mechanical supports; steady heat needs a\nprescribed temperature or an ambient convection/radiation boundary. Free-free modal\nand unconstrained dynamics are valid, and transient heat may be insulated. These\npre-mesh warnings identify missing inputs; only the resolved solve can establish that\nevery connected component is restrained and every selected Set contains nodes.\nStep-specific warnings carry their exact `step` identity separately from the display\nlocation in `where`, so hosts can scope blockers without parsing names or prose.\n`nonlinearTolerance` and `nonlinearMaxIterations` govern any Step whose system depends\non its own answer — a radiation load, or geometric nonlinearity — and are ignored by a\nStep that is linear.\nHeat Results report net applied power, positive removed heat and stored-energy rate;\ntransient powers belong to the last θ-method integration stage (radiation uses weighted\nendpoint fluxes), while temperature fields belong to its endpoint.\nA modal Step's `after` is optional and means stress stiffening: naming a solved\n`static` or `static-nonlinear` Step adds that state's geometric stiffness to K, so the\nfrequencies are those of the *preloaded* structure (tension up, compression down, zero\nat the buckling load), and `prestressFrom` on the Result names the preload Step. Naming\na heat Step instead keeps the existing meaning, the temperature field alone, and\nstiffens nothing.\nA harmonic Step requires `after` to name a Step whose `modal` Result is current: it\nsuperposes those mode shapes rather than solving anything (ADR 0020), so its accuracy is\nbounded by that Step's `nModes`. It drives its own Loads at each swept frequency and\nanswers a nodal amplitude and a phase lag per retained frequency; `displacement` is the\namplitude at the frequency of peak response. Its Constraints may only hold DOFs at zero\n— a moving support is base excitation, which this procedure does not do."
        return self._call("dispatch", StepAddArgs(name=name, procedure=procedure, constraints=constraints, loads=loads, output=output, after=after, n_modes=n_modes, shift=shift, dt=dt, t_end=t_end, theta=theta, output_every=output_every, dt_factor=dt_factor, amplitude=amplitude, initial=initial, alpha=alpha, rayleigh_alpha=rayleigh_alpha, rayleigh_beta=rayleigh_beta, initial_velocity=initial_velocity, increments=increments, max_cutbacks=max_cutbacks, nonlinear_tolerance=nonlinear_tolerance, nonlinear_max_iterations=nonlinear_max_iterations, f_start=f_start, f_stop=f_stop, points=points, sweep=sweep, damping_ratio=damping_ratio, damping_ratios=damping_ratios, psd=psd).wire())

    def step_remove(self, *, name: str) -> Any:
        "Remove a Step and the Result it produced, if any. Constraints and Loads it referenced\nstay in the Model and can be reused by other Steps. Fails with `in-use` while another\nStep names it in `after`; re-issue that dependent Step without the reference first."
        return self._call("dispatch", StepRemoveArgs(name=name).wire())

    def step_reorder(self, *, order: Any) -> Any:
        "Set the run order of Steps; `order` must list every Step name exactly once and keep each\nStep after the prerequisite named by its `after` field. Steps run in this order and a\nlater Step may inherit state (a temperature field) from an earlier one."
        return self._call("dispatch", StepReorderArgs(order=order).wire())

    def solve_run(self, *, step: str, solver: Any = OMIT, tolerance: Any = OMIT, max_iterations: Any = OMIT) -> Any:
        "Run a Step. Checks well-posedness first (materials, constraints, rigid-body modes,\nelement quality) and refuses with a suggested fix. Returns extremes, reactions and every\nomitted optional material property the successful solver actually read as zero; always\ncheck that reactions balance the applied loads before trusting a stress. A Step with\n`after` requires its predecessor's Result to match the current Model state; after an edit,\nsolve the predecessor again before continuing the chain.\nDirect linear solves verify their residual too: nonfinite or excessive residuals return\nsolve.stalled instead of storing a Result. Static and non-radiating steady direct solves use `tolerance`\n(default 1e-10) with the same 100-fold f64 roundoff allowance as iterative refinement. The\ndirect tolerance must be positive and its 100-fold allowance finite, or a schema error is returned.\nModal solves verify every requested eigenpair's normwise backward residual against\n`tolerance` and return solve.stalled without storing a Result when `maxIterations`\nsubspace sweeps are exhausted. The reported residual is the largest requested-pair\nresidual; it certifies algebraic backward accuracy, not frequency or mesh accuracy.\nResolved Ritz values must also stabilize to relative change 1e-10. Values unresolved\nat the per-mode Rayleigh-contraction roundoff scale carry modal.unresolved-frequency\nwarnings; their backward residual passed, but relative frequency convergence is not certified.\nOn Windows, direct numeric factorization is sequential to avoid a verified faer defect;\nassembly and triangular solves retain the engine thread count."
        return self._call("dispatch", SolveRunArgs(step=step, solver=solver, tolerance=tolerance, max_iterations=max_iterations).wire())

    def study_converge(self, *, step: str, sizes: Any, quantity: Any, restore: Any = OMIT) -> Any:
        "Re-mesh at each size, re-solve the Step and report the quantity of interest per size,\nthe observed convergence rate and a Richardson estimate of the converged value. Sizes\nmay have unequal refinement ratios. Three distinct positive sizes are needed for a\nfinite limit of the form q(h) = q* + C h^p with p > 0; otherwise the estimate and rate\nare unavailable. Restores the previous mesh settings afterwards unless `restore` is false.\nUses the Step's actual procedure: static and steady heat measure equilibrium fields;\ntransient heat and explicit dynamics measure the final field at the configured tEnd\nwith the Step's time settings unchanged. Modal Steps are unsupported because a mode\namplitude is not a mesh-independent quantity; compare frequencies with\nsolve.run/query.result instead. Steps with after are unsupported: solve their\ndependencies and target at each mesh explicitly."
        return self._call("dispatch", StudyConvergeArgs(step=step, sizes=sizes, quantity=quantity, restore=restore).wire())

    def study_adapt(self, *, step: str, target_error: float, max_iterations: Any = OMIT, max_elements: Any = OMIT, marking_fraction: Any = OMIT, refinements: Any = OMIT) -> Any:
        "Solve, estimate local spatial error with ZZ recovery, refine the largest\ncontributions, and repeat until targetError or maxIterations is reached.\nLeaves the last solved mesh and Result installed. Supports planar tri3/solid\ntet4 with static, heat-steady or heat-transient Steps without after. Transient\nruns restart at the configured initial state and estimate the final field;\nthis does not estimate time error or adapt/coarsen within a time integration.\nerrorEstimate is a dimensionless element field; its squared sum is the squared\nglobal relative estimate. Recovery is an indicator, not a certified error bound.\nRefines the existing boundary approximation without CAD projection. Exceeding\nmaxElements or cancellation rolls back the entire Command."
        return self._call("dispatch", StudyAdaptArgs(step=step, target_error=target_error, max_iterations=max_iterations, max_elements=max_elements, marking_fraction=marking_fraction, refinements=refinements).wire())

    def journal_undo(self, *, steps: Any = OMIT, expected_journal: Any = OMIT) -> Any:
        "Undo the last `steps` Commands (default 1), restoring the Model and orphaning any\nResult produced after that point. Not recorded in the Journal. If `expectedJournal` is\nsupplied, it must equal the complete-history `hash` from `query.journal` at execution time; otherwise\nnothing is undone. Use this guard for a saved turn boundary while other callers can edit."
        return self._call("dispatch", JournalUndoArgs(steps=steps, expected_journal=expected_journal).wire())

    def journal_redo(self, *, steps: Any = OMIT) -> Any:
        "Redo the last `steps` undone Commands (default 1) by re-applying them; a redone solve\nre-solves. Not recorded in the Journal; any new Command after an undo clears the redo stack."
        return self._call("dispatch", JournalRedoArgs(steps=steps).wire())

    def plugin_load(self, *, name: str, kind: Any, language: Any, source: Any, manifest: Any = OMIT) -> Any:
        "Load a Plugin filling one Extension Point (a material law, element, load, post\nquantity, mesher or procedure) in TypeScript, WGSL or wasm; recorded in the Journal by\ncontent hash. Not available yet: returns unsupported until the plugin phase lands."
        return self._call("dispatch", PluginLoadArgs(name=name, kind=kind, language=language, source=source, manifest=manifest).wire())

    def query_portable_project(self) -> Any:
        "Lossless portable project snapshot, including all retained solved meshes and f64 fields.\nHost storage is separate; capture the checked ReadReply stamp with this owned value."
        return self._call("query", QueryPortableProjectArgs().wire())

    def query_model(self) -> Any:
        "Everything about the Model in one read: bodies with volumes and materials, imported\nface patches with paste-ready naming predicates, named Sets, constraints, loads with\ntheir totals, steps and predecessor links, mesh settings, and the well-posedness warnings\nthat would block a solve. Material properties include thermal expansion `alpha` in 1/K,\nconductivity `k` in W/(m K), specific heat `cp` in J/(kg K), and the supplied `source`.\nExpansion and conductivity preserve one isotropic value or three material-axis values.\nRead this before changing anything."
        return self._call("query", QueryModelArgs().wire())

    def query_document(self) -> Any:
        "The complete authoritative Model file and Journal in SI, with the real Model hash and\nrevision. Retains selected display-unit strings without formatting a display summary;\nuse this to save even when query.model reports unit.display. This read changes neither\nthe Model nor retained Results. Hosts apply their exact UTF-8 save encoder and byte limit\nbefore writing; this Query performs no I/O or replacement validation."
        return self._call("query", QueryDocumentArgs().wire())

    def query_definition(self, *, kind: Any, name: str) -> Any:
        "The complete upsert Command for an existing object's current definition, with exact\nSI quantities. Use it to populate an edit form; change its arguments and dispatch it\nto apply. Display summaries are rounded and must never be used to reconstruct edits.\nAuto-generated Sets and mesher-owned Bodies have no editable object definition."
        return self._call("query", QueryDefinitionArgs(kind=kind, name=name).wire())

    def query_mesh(self) -> Any:
        "Counts and sanity of the current Mesh (nodes, elements, element kind, DOF, bounding box,\nedge lengths, Sets with their resolved sizes, quality). Builds the Mesh if needed."
        return self._call("query", QueryMeshArgs().wire())

    def query_set(self, *, name: str) -> Any:
        "What a Set resolved to on the current Mesh: kind, count, bounding box, geometric measure\nand corner-node centroid. Solid volumes integrate every original shape node, including\nTet10/Hex20 midside nodes: tetrahedron degree3 and tensor degree5 per coordinate are\nsufficient for their Jacobian determinants, up to f64 roundoff. Surface areas and edge\nlengths use original tangents. Linear triangles and lines are exact up to roundoff;\nbilinear faces use Gauss2. Curved norms are numerical, using Gauss3 for Quad8/Line3\nand symmetric triangle degree5 for Tri6.\nCurved area/length accuracy improves under refinement; no corner skin is substituted.\nFace Sets also report pressureArea from the load boundary quadrature,\nincluding thickness or radial weighting (plane strain: one metre of depth). Pressure\ntimes pressureArea is a scalar integral, not a net vector force. Shell pressureArea is\nthe original midsurface area without requiring Material/Section; curved physical shell\nloads use the Section's top/bottom offsets. Builds the Mesh if needed.\nThe centroid averages resolved node coordinates; authored imported NSETs include\nunused source labels. A bounded fixed-order fallback prevents a finite coordinate\nmean overflowing through rounding, while preserving existing finite mean results."
        return self._call("query", QuerySetArgs(name=name).wire())

    def query_result(self, *, result_id: Any = OMIT, step: Any = OMIT) -> Any:
        "Summary of a Step's Result: solver info, extremes of every field with their location,\nreactions per constraint, applied totals, solver-used omitted material assumptions, and\nwhether the Result is stale (the Model changed after it was solved). Check the reaction\nbalance and assumptions first."
        return self._call("query", QueryResultArgs(result_id=result_id, step=step).wire())

    def query_results(self) -> Any:
        "Catalogue of the eight most recent successful solve instances, oldest first. Reads do\nnot extend retention. Evicted ids are unavailable; Model import/new clears records."
        return self._call("query", QueryResultsArgs().wire())

    def query_surface(self, *, step: Any = OMIT, result_id: Any = OMIT) -> Any:
        "The triangulated boundary of a retained Result's solved Mesh, with f64 SI positions,\noriginal node indices, Body identities and face-Set memberships. Explicit resultId\nreads that immutable solve even after Model edits; an omitted id selects the latest\ncompatible Result for step (or the last solved Step), rejecting stale or missing Results.\nThis never substitutes the current Mesh or a geometry preview. Use query.results for ids."
        return self._call("query", QuerySurfaceArgs(step=step, result_id=result_id).wire())

    def query_field(self, *, step: Any = OMIT, result_id: Any = OMIT, field: str) -> Any:
        "A final field in SI with explicit entity layout, selected by solve instance or the current per-Step default.\nField names include mode:k for one-based modal/buckling shapes owned by the Result\n(`1 <= k <= query.result.modeCount`) and stressPly:k:bottom/top\nfor laminate ply faces (k starts at 1, bottom to top within each Section). Ply stresses\nare global xx, yy, zz, xy, xz, yz in Pa, unaveraged per element node; elements without\nthat ply carry zeros. Both sides of an interface remain distinct. Explicit ids use solved metadata;\nomitted ids refuse stale Results. Retained samples use query.frame's existing protocol."
        return self._call("query", QueryFieldArgs(step=step, result_id=result_id, field=field).wire())

    def query_difference(self, *, left: Any, right: Any, onto: Any) -> Any:
        "Subtract two explicitly retained nodal fields as `left - right` on either Result's\nMesh. Unequal meshes use finite-element interpolation and report uncovered nodes as\nnull values; nonfinite arithmetic is a structured error. No current Result, display\nconversion, or node-number pairing is implied. Each operand may independently select\na retained primary frame with the existing exact/nearest FrameSample protocol; resolved\nindices and physical times are returned. Historical derived fields are unavailable.\nOmitted samples preserve final-field comparison. There is no temporal interpolation."
        return self._call("query", QueryDifferenceArgs(left=left, right=right, onto=onto).wire())

    def query_frames(self, *, result_id: Any = OMIT, step: Any = OMIT) -> Any:
        "Catalogue of retained primary-field frames for heat-transient, explicit or amplitude-driven static Steps (default: last solved Step).\nIndex 0 is the initial state; indices count retained frames, not integration steps.\nMetadata remains available for stale Results. No nodal values are copied by this Query."
        return self._call("query", QueryFramesArgs(result_id=result_id, step=step).wire())

    def query_frame(self, *, result_id: Any = OMIT, step: Any = OMIT, index: Any = OMIT, sample: Any = OMIT, field: Any = OMIT) -> Any:
        "One retained primary field from a heat-transient, explicit or amplitude-driven static Step. Supply exactly one of zero-based retained index\nor sample (retained index / physical time with exact or nearest selection). Time\nselection uses the same roundoff tolerance, earlier-tie rule and no-extrapolation\npolicy as sampled probe/path. Values are SI,\ncomponent-fastest, with three components per node, matching final FieldData: a 2D\ndisplacement has zero z; temperature occupies x with zero y/z. Defaults to the retained\nprimary field. Derived fields were not retained and are refused. Omitted resultId refuses result.stale."
        return self._call("query", QueryFrameArgs(result_id=result_id, step=step, index=index, sample=sample, field=field).wire())

    def query_probe(self, *, result_id: Any = OMIT, step: Any = OMIT, field: Any, component: Any = OMIT, sample: Any = OMIT, at: Any) -> Any:
        "A field value at a point (default: the last solved Step). Nodal fields are\ninterpolated; errorEstimate returns the containing element's constant value\nwith interpolated=false. Shared-face ties use the lowest element id. Component\nindices: displacement 0..3, stress Voigt 0..6 (xx, yy, zz, xy, xz, yz), principal 0..3.\nOptional sample selects a retained primary-field frame; omitted means the final field.\nOmitted resultId refuses `result.stale` after edits; an explicit id uses its solved Mesh."
        return self._call("query", QueryProbeArgs(result_id=result_id, step=step, field=field, component=component, sample=sample, at=at).wire())

    def query_path(self, *, result_id: Any = OMIT, step: Any = OMIT, field: Any, component: Any = OMIT, sample: Any = OMIT, from_: Any, to: Any, n: int) -> Any:
        "A field sampled at `n` points along the line from `from` to `to`, for a line plot.\nOptional sample selects a retained primary-field frame; omitted means the final field.\nOmitted resultId refuses `result.stale` after edits; an explicit id uses its solved Mesh."
        return self._call("query", QueryPathArgs(result_id=result_id, step=step, field=field, component=component, sample=sample, from_=from_, to=to, n=n).wire())

    def query_cost(self, *, step: str) -> Any:
        "Cost before solving: DOF, matrix non-zero bounds, exact retained-frame schedule and\ncounted peak memory. Counting uses at most 16 MiB scratch after meshing. Feasibility is\nfalse above a fixed 1.5 GiB planning budget, otherwise unknown because solver fill,\nallocator overhead and host serialization are excluded.\nUse before large solves; this query does not promise that a solve fits the current host."
        return self._call("query", QueryCostArgs(step=step).wire())

    def query_journal(self, *, from_seq: Any = OMIT) -> Any:
        "The Journal: every applied Command with the Model hash after it, and whether undo or\nredo is possible. `fromSeq` returns only entries at or after that sequence number."
        return self._call("query", QueryJournalArgs(from_seq=from_seq).wire())

    def query_journal_diff(self, *, base: Any) -> Any:
        "Compare this Model's Journal with a supplied base Journal. Returns the shared causal\nprefix and each ordered divergent tail: removed entries belong to `base`, added entries\nto the current Journal. Entry identity is the typed Command plus `hashAfter`; `seq` is\nonly a displayed location and is ignored. Entries after the first divergence are not\nre-aligned. This read never replays either Journal."
        return self._call("query", QueryJournalDiffArgs(base=base).wire())

    def query_script(self) -> Any:
        "The Journal as a TypeScript script against the `fem` API that reproduces the Model line by\nline; what the Script panel shows and what script.run accepts back."
        return self._call("query", QueryScriptArgs().wire())

    def query_convert(self, *, quantity: Any, to: str) -> Any:
        "Convert a quantity to another unit of the same dimension (\"2 MPa\" to \"psi\"); an error\nnames the dimensions when they differ. Handy for checking inputs before using them.\nRejects nonfinite values and nonzero scaling that rounds to zero, including input\nscaling before adding a temperature offset. Surviving subnormals, ordinary f64\nrounding and affine zeros (273.15 K to 0 degC) remain valid."
        return self._call("query", QueryConvertArgs(quantity=quantity, to=to).wire())

    def query_abaqus_dependencies(self, *, text: str, source_name: Any = OMIT, source_files: Any = OMIT) -> Any:
        "Inspect the supplied Abaqus bundle for missing INCLUDE and NODE/ELEMENT INPUT files.\nUses the same bounded lexer and safe relative-path graph as conversion. This read\nperforms no model/physics conversion or file/network I/O; hosts can acquire listed\nfiles through their captured scoped I/O and repeat until the bundle is complete.\nThe actual conversion still rejects missing files and never publishes partial data."
        return self._call("query", QueryAbaqusDependenciesArgs(text=text, source_name=source_name, source_files=source_files).wire())

    def query_convert_abaqus(self, *, text: str, name: str, body: str, mode: Any, unit_length: Any, unit_force: Any = OMIT, unit_time: Any = OMIT, source_name: Any = OMIT, source_files: Any = OMIT, sha256: str) -> Any:
        "Convert a bounded Abaqus text deck to checked portable Commands without mutating\nthe active Model or solving. Explicit positive unitLength and static-mode unitForce\ndefine source units; coordinates/displacements scale by L, forces by F and stress\nby F/L². Structural instances, labels, exact Sets and surfaces are normalized by\nthe typed deck reader. The report records all translated analysis Steps and notes\nrecognized requests whose output/increment execution differs from FEM Lab.\nStatic mode imports constant isotropic materials and exact nonoverlapping solid\nsection regions covering every element, direct or solid symbolic BOUNDARY,\nCLOAD and uniform DLOAD Pn / DSLOAD P pressure. Multiple small-displacement static\nSteps retain effective inherited loads/supports; OP=NEW resets that family's state,\nOP=MOD updates it. Conflicting repeated definitions within one Step fail explicitly.\nEach Step configures its final linear equilibrium, without source increment history.\nUnsupported physics/formulations/parameters fail rather than being discarded.\nMesh mode configures no analysis. Neither mode infers missing physical units.\nInput and serialized response are bounded to 16 MiB; hosts must privately prepare\nall returned Commands through Candidate and publish one validated replacement."
        return self._call("query", QueryConvertAbaqusArgs(text=text, name=name, body=body, mode=mode, unit_length=unit_length, unit_force=unit_force, unit_time=unit_time, source_name=source_name, source_files=source_files, sha256=sha256).wire())

    def query_material_library(self, *, name: Any = OMIT) -> Any:
        "Primary-source material data with dimensions, grade, condition, temperature and a source\nfor every reported property. With no `name`, lists the stable catalogue. With a canonical\nid, name or unambiguous alias, returns that entry. Missing properties are explicit nulls:\nnever infer them before material.add. Copy the entry's `materialAddSource` into that\nCommand's `source` so the Journal preserves provenance."
        return self._call("query", QueryMaterialLibraryArgs(name=name).wire())

    def query_objects(self, *, kinds: Any = OMIT) -> Any:
        "Every nameable thing in the Model as `@`-mention references (`body:beam`, `set:beam.top`,\n`material:steel`, `journal:12`), with a one-line summary each; the mention picker's index."
        return self._call("query", QueryObjectsArgs(kinds=kinds).wire())

    def query_report(self, *, step: Any = OMIT, include: Any = OMIT) -> Any:
        "The whole analysis as one Markdown calculation note: assumptions, geometry, materials,\nmesh and quality, loads with totals, results with the reaction balance, the verification\nchecks with a hand calculation where one applies, and the Journal as an appendix. Nothing\nin it depends on the clock or the machine, so two runs of the same Journal produce\nbyte-identical text. `step` reports one Step instead of every solved one; `include` picks\nsections. Automatic hand references require a current static Step on an uncut 3D lattice\nbox with one fully clamped end and one single-component force on the opposite end;\nother cases explicitly report no applicable automatic reference. Formulas are `$$…$$` for KaTeX."
        return self._call("query", QueryReportArgs(step=step, include=include).wire())

    def query_capabilities(self) -> Any:
        "What this engine can do here: GPU presence and adapter name, thread count, engine and\nschema versions. Hosts add browser facts (cross-origin isolation, local or remote engine)."
        return self._call("query", QueryCapabilitiesArgs().wire())

class AsyncAPI:
    _call: Any
    async def model_new(self, *, name: str, description: Any = OMIT) -> Any:
        "Start a new, empty Model and Journal with this name. Discards the current Model, its\nResults and the undo history; it is the first entry of every Journal, so call it once\nat the start, never to \"reset\" mid-way (use journal.undo for that)."
        return await self._call("dispatch", ModelNewArgs(name=name, description=description).wire())

    async def model_set_units(self, *, units: Any) -> Any:
        "Choose the display units used by Queries and the UI (for example mm, kN, MPa, kW). Storage\nstays SI and every input may still use any unit of the right dimension; this only\nchanges how values are reported back. A scalar that cannot fit in the selected unit\nproduces `unit.display` when queried or reported, without altering its stored SI data.\nChoose larger or SI display units to read it; formatting never silently changes units."
        return await self._call("dispatch", ModelSetUnitsArgs(units=units).wire())

    async def model_set_name(self, *, name: str) -> Any:
        "Change the Model's display name without resetting geometry, history or solved Results.\nA name-only edit is undoable and changes the full Model/Journal identity, but does not\nchange the Result-validity fingerprint. Whitespace-only names are rejected."
        return await self._call("dispatch", ModelSetNameArgs(name=name).wire())

    async def model_set_idealisation(self, *, idealisation: Any) -> Any:
        "Set the idealisation: 3D solids (default), plane stress with a thickness, plane strain,\nor axisymmetric (x = radius, y = axis). 2D idealisations need Sheet bodies and 3D needs\nsolid bodies; mixing them makes the Model ill-posed."
        return await self._call("dispatch", ModelSetIdealisationArgs(idealisation=idealisation).wire())

    async def model_rename(self, *, kind: Any, name: str, to: str) -> Any:
        "Rename a Body, Material, Set, Constraint, Load or Step and every reference to it. A Body\nrename also renames its auto faces (`<name>.xmin` …). Fails with name.taken if `to`\nalready exists in that kind. Bodies and Sets also share the geometry namespace with\ncuts and point masses, so their new name cannot shadow any geometry owner.\nMapped and swept mapped Bodies also rename their mesher\ngeometry, named Face/Body-region selectors and material association."
        return await self._call("dispatch", ModelRenameArgs(kind=kind, name=name, to=to).wire())

    async def model_duplicate(self, *, kind: Any, name: str, as_: str) -> Any:
        "Copy an object under a new name. A Body copy shares nothing with the original; a Step\ncopy references the same Constraints and Loads. Useful for \"the same load case but\ntwice the pressure\": duplicate, then re-issue the create Command with the new value.\nA mapped or swept mapped Body cannot be copied: the Model has one mesher geometry\nslot. Returns unsupported without changing the Model; use model.rename or mesh.set.\nA Body or Set copy cannot reuse a Body, cut, named Set or point-mass name."
        return await self._call("dispatch", ModelDuplicateArgs(kind=kind, name=name, as_=as_).wire())

    async def geometry_add_box(self, *, name: str, size: Any, at: Any = OMIT) -> Any:
        "Add an axis-aligned box Body with its minimum corner at `at` (default the origin). Its\nsix faces are auto-named `<name>.xmin`, `<name>.xmax`, … `<name>.zmax` and can be used\ndirectly in constraints and loads. Re-issuing with an existing name replaces the Body\nwhile preserving its material, section and cuts; incompatible or consuming cuts reject\nthe replacement without changing the Model."
        return await self._call("dispatch", GeometryAddBoxArgs(name=name, size=size, at=at).wire())

    async def geometry_subtract_box(self, *, name: str, from_: str, size: Any, at: Any) -> Any:
        "Cut an axis-aligned box out of the Body `from` (a hole, notch or opening). The cut's\nwalls are auto-named `<name>.xmin` … and refer to the faces of the hole, so a pressure\non `hole.zmin` acts on the hole's floor. Cuts that remove everything are an error.\nMapped and swept mapped Bodies return unsupported; edit their blocks with mesh.set."
        return await self._call("dispatch", GeometrySubtractBoxArgs(name=name, from_=from_, size=size, at=at).wire())

    async def geometry_add(self, *, name: str, shape: Any) -> Any:
        "Add a Body from any shape: box, cylinder, sphere, an extruded or revolved sketch, a\n2D sheet, or booleans of those. Faces are auto-named `<name>.<tag>` from the shape\n(`side`, `top`, sketch segment tags, …); list them with query.model. Lengths need units.\nReplacing an existing Body preserves its material, section and cuts, and validates the\nresulting shape before changing the Model."
        return await self._call("dispatch", GeometryAddArgs(name=name, shape=shape).wire())

    async def geometry_add_line(self, *, name: str, points: Any, members: Any = OMIT, divisions: Any = OMIT, kind: Any = OMIT) -> Any:
        "Add a Body made of straight line members: a truss or a frame. `points` are the joints,\nin order, and `members` are index pairs into them; the default is a chain 0-1, 1-2, and\nso on. Each member is cut into `divisions` elements of equal length (default 1). Joint\n`i` becomes the node Set `<name>.p<i>`, which is what a constraint or a nodal force\ntargets, and joints of different line Bodies that sit at the same point are welded into\none node when the Mesh is built. `kind` is `truss` (the default: pin-jointed bars that\ncarry axial force only, so hold enough joints that none can drift sideways — an\nunder-braced truss is singular and fails in the solver, not here) or `beam` (Timoshenko\nbeams carrying axial force, shear, bending and torsion; every joint then has three\nrotations rx, ry, rz as well as ux, uy, uz, so constraint.fix clamps it and\nconstraint.pin pins it, and load.moment can act on it). Either way give the Body a\nSection with section.assign as well as a Material. Line Bodies need the 3D\nidealisation and are not cut, meshed or previewed as solids. Replacing a Body that has\ncuts therefore fails without changing the Model."
        return await self._call("dispatch", GeometryAddLineArgs(name=name, points=points, members=members, divisions=divisions, kind=kind).wire())

    async def geometry_subtract(self, *, name: str, from_: str, shape: Any) -> Any:
        "Cut a shape out of the Body `from`. The cut's faces are auto-named `<name>.<tag>` (for a\ncylinder: `<name>.side`), which is how you load or fix the wall of a hole. The shape\nis positioned in world coordinates, so use its `at` or a transform to place it.\nMapped and swept mapped Bodies return unsupported; edit their blocks with mesh.set."
        return await self._call("dispatch", GeometrySubtractArgs(name=name, from_=from_, shape=shape).wire())

    async def geometry_import(self, *, name: str, format: Any, data: str, encoding: Any = OMIT, sha256: Any = OMIT, unit_length: Any, feature_angle: Any = OMIT, simplify_below: Any = OMIT) -> Any:
        "Import a triangle-mesh geometry file as a Body: the file travels *inside* the Command\nas `data`, so a Journal replays with no external file, no network and no file system,\non any host. STL carries no units, so `unitLength` says what one file unit is (`1 mm`\nfor a part drawn in millimetres). The mesh is welded into a watertight solid, so\nvolume, mass, booleans and meshing all work on it; its faces are patches of triangles\nthat meet more smoothly than `featureAngle` (30 degrees by default), auto-named\n`<name>.face0`, `<name>.face1`, ... largest area first. Those numbers move when the\nfile changes, so for anything you will re-import, name the faces you need with\ngeometry.nameFace predicates (a plane, a cylinder): those are re-resolved at every\nremesh and survive a re-import. `simplifyBelow` collapses features smaller than the\ngiven length, which is the honest half of defeaturing; there is no fillet, chamfer or\nshell. Re-import preserves the Body's material, section and cuts, and validates the\nresulting shape before changing the Model. Give `sha256` to have the engine verify the\ndata is the file you meant."
        return await self._call("dispatch", GeometryImportArgs(name=name, format=format, data=data, encoding=encoding, sha256=sha256, unit_length=unit_length, feature_angle=feature_angle, simplify_below=simplify_below).wire())

    async def geometry_name_face(self, *, name: str, of: str, where: Any) -> Any:
        "Name a face Set of Body `of` by a geometric rule (plane, normal, box, cylinder, or any\nof those) so constraints and loads can target it. Rules are re-evaluated after every\nremesh, so the Set survives refinement. Body `of` may be explicit geometry or the\nimplicit Body defined by a mapped or swept mapped mesher. The rule selects only that\nBody's actual mesh boundary. Prefer the auto face names when one fits.\nReissuing replaces an existing named Set; a Body, cut or point-mass name is reserved."
        return await self._call("dispatch", GeometryNameFaceArgs(name=name, of=of, where=where).wire())

    async def geometry_name_region(self, *, name: str, where: Any) -> Any:
        "Name a node/element Set by a region rule (a box or a whole Body), for point-like\nconstraints, nodal forces and probes. Node sets from regions are exact at mesh nodes;\nuse a box slightly larger than the points you mean. A whole-Body rule also accepts\nthe implicit Body defined by a mapped or swept mapped mesher.\nReissuing replaces an existing named Set; a Body, cut or point-mass name is reserved."
        return await self._call("dispatch", GeometryNameRegionArgs(name=name, where=where).wire())

    async def geometry_remove(self, *, name: str) -> Any:
        "Remove a Body, a cut, a named Set or a point mass from their shared geometry namespace.\nFails with in-use listing the constraints, loads\n(including temperature and volumetric heat sources), named selectors or free-mesher\ngeometry references that still use a Body; remove or retarget those first. Removing\na mapped or swept mapped Body clears its mesher and material association, preserving\nunrelated explicit geometry and Materials."
        return await self._call("dispatch", GeometryRemoveArgs(name=name).wire())

    async def geometry_add_mass(self, *, name: str, at: Any, mass: Any) -> Any:
        "Add a lumped point mass at a coordinate: one node of its own, carrying mass and nothing\nelse. It contributes to the mass matrix (so it changes modal frequencies) and to gravity\n(m·g at that point), and has no stiffness whatever, so it must be attached to the model\nwith constraint.couple: on its own it makes the Model ill-posed and solve.run refuses.\nThe point is also a node Set of the same name, so constraint.couple, constraint.fix,\nload.force and query.set target it by name. Re-issuing an existing point-mass name\nreplaces it; other Body, cut and named-Set names are reserved. geometry.remove deletes\nit. It carries no rotary inertia — a node has no rotations —\nso it models a compact mass, not a flywheel."
        return await self._call("dispatch", GeometryAddMassArgs(name=name, at=at, mass=mass).wire())

    async def material_add(self, *, name: str, E: Any = OMIT, nu: Any = OMIT, orthotropic: Any = OMIT, orientation: Any = OMIT, rho: Any = OMIT, alpha: Any = OMIT, k: Any = OMIT, cp: Any = OMIT, yield_: Any = OMIT, plasticity: Any = OMIT, source: Any = OMIT) -> Any:
        "Define a Material: elastic stiffness is either isotropic, by Young's modulus `E` and\nPoisson's ratio `nu` (0 ≤ ν < 0.5), or orthotropic, by the `orthotropic` block — never\nboth. A heat-only Material omits both stiffness forms and gives positive conductivity\n`k`; `rho` and `cp`, when stated, must also be positive and are required by heat-transient.\nHeat-only Materials may retain `alpha` and `yield` for later structural use; `plasticity`\nrequires isotropic stiffness, and mechanical Steps require elastic stiffness.\n`orientation` turns the material axes (wood grain, fibre direction, rolling\ndirection) away from the global axes; without it they are the global axes. Density `rho`\nis needed for gravity and modal analysis, `alpha` for thermal loads, `k` and `cp` for\nheat transfer; `source` records where the numbers came from. `yield` is the yield\nstress the safety factor and the `plasticity` block read; `plasticity` makes the\nmaterial elastic–plastic (J2, isotropic hardening) in `static-nonlinear` Steps. Re-issuing\nwith an existing name edits the material in place, so an omitted `orientation` or\n`plasticity` clears the previous one."
        return await self._call("dispatch", MaterialAddArgs(name=name, E=E, nu=nu, orthotropic=orthotropic, orientation=orientation, rho=rho, alpha=alpha, k=k, cp=cp, yield_=yield_, plasticity=plasticity, source=source).wire())

    async def material_assign(self, *, material: str, bodies: Any) -> Any:
        "Assign a Material to one or more Bodies. Imported element regions are editable Bodies;\nassigning the source owner supplies their default, while region assignments override it.\nEvery element-owning Body needs a Material before solving; a missing assignment is\nreported by query.model and blocks solve.run."
        return await self._call("dispatch", MaterialAssignArgs(material=material, bodies=bodies).wire())

    async def material_remove(self, *, name: str) -> Any:
        "Remove a Material that is not assigned to any Body. Fails with in-use listing the Bodies\nthat still use it; assign them another Material first with material.assign."
        return await self._call("dispatch", MaterialRemoveArgs(name=name).wire())

    async def section_add(self, *, name: str, shape: Any) -> Any:
        "Define a section: homogeneous shell thickness, a bottom-to-top laminate stack\nof 1–256 plies with named Materials and unit-bearing angles, or a line Body cross-section\n(`geometry.addLine`): rectangle, circle, tube, I, channel, or properties given directly. A line member has no cross-section\ngeometry of its own, so the Section is where its area, second moments, torsion constant,\nshear factors and extreme-fibre distances come from. Re-issuing with an existing name\nedits the section in place. Assign it to Bodies with section.assign."
        return await self._call("dispatch", SectionAddArgs(name=name, shape=shape).wire())

    async def section_assign(self, *, section: str, bodies: Any, orientation: Any = OMIT) -> Any:
        "Assign a Section to one or more Bodies, including imported element regions. A region\noverrides the source owner Section; an unassigned region inherits that default.\nEvery line or shell Body needs a Section before solving;\none without it is reported by query.model warnings and blocks solve.run with\nmodel.no-section. A shell needs a shell thickness section, a line member needs a\ncross-section, and a solid gets its section from its geometry. `orientation` names the global\naxis the section's local z (its `height` direction, the one `iY` resists bending along)\nfollows for the beams of these Bodies: local z is that axis made perpendicular to each\nmember, and local y completes the right-handed triad (y = z × x). It may not lie along\na member. Without it the rule is: local z follows global Z, so a horizontal beam has\nits height vertical; a member within 1e-6 of vertical follows global X instead, so a\ncolumn's local z points along +X. `iZ` then resists bending along local y. Trusses\nignore it. For laminate shells, orientation instead selects the tangent projection\nof that global axis as the zero-angle ply direction. A normal axis is rejected.\nWithout it ply angles use the midsurface's first parametric direction."
        return await self._call("dispatch", SectionAssignArgs(section=section, bodies=bodies, orientation=orientation).wire())

    async def section_remove(self, *, name: str) -> Any:
        "Remove a Section that is not assigned to any Body. Fails with in-use listing the Bodies\nthat still use it; assign them another Section first with section.assign."
        return await self._call("dispatch", SectionRemoveArgs(name=name).wire())

    async def mesh_set(self, *, mesher: Any, order: Any = OMIT, formulation: Any = OMIT, simplices: Any = OMIT, refinement: Any = OMIT) -> Any:
        "Choose the Mesher and element settings; the Mesh is rebuilt lazily when needed. `order`\n1 gives linear elements, 2 quadratic (more accurate in bending and at stress peaks).\n`formulation: mean-dilatation` gives small-strain Hex8 the volume-averaged B-bar\nstrain used by Abaqus C3D8; other kinds keep full integration. Existing full Journals\nretain their original pointwise strain. Mean-dilatation Hex8 cannot run finite deformation.\n`formulation: full` is the textbook linear element that locks in bending: keep the\ndefault incompatible modes or use order 2 when bending matters. Mesher-defined geometry\nowns a Body name distinct from explicit Bodies, cuts, named Sets and point masses.\nKeeping that name preserves its material;\nchanging/removing it requires no remaining Body references and clears its material.\nUse model.rename to change an implicit Body name while preserving its references.\n`simplices: true` splits hexes into tetrahedra (tet4/tet10) and quads into triangles\n(tri3/tri6), preserving named faces. It does not make a free tetrahedral mesh of curved\ngeometry: the selected mesher still determines the boundary approximation, and the `tet`\nmesher is the one that meshes a curved solid freely. `formulation` has no effect when\n`simplices` is true, or under the `tet` mesher, because simplex elements have no\nincompatible modes. Imported sources retain authored labels/connectivity and exact Sets,\ndefault to full integration, and require solid3d, no simplex split/refinement.\nTheir element kinds determine interpolation; order 1 means retain the authored source, including quadratic nodes.\nRemoving or emptying a referenced imported Set fails without mutation."
        return await self._call("dispatch", MeshSetArgs(mesher=mesher, order=order, formulation=formulation, simplices=simplices, refinement=refinement).wire())

    async def mesh_export(self, *, format: Any, step: Any = OMIT) -> Any:
        "Write the current Mesh out as text the host saves; the Mesh is built first if it is\nstale. `vtu` is the VTK XML UnstructuredGrid that ParaView opens, carrying the element\nid and the Body index as cell data. Name a `step` to add that Step's result fields as\npoint data — displacement, reaction, stress and von Mises — so ParaView colours by them.\nResult fields require the Model state they were solved on; `result.stale` means run\n`solve.run` on that Step again before exporting it with the current Mesh.\n`msh`, `inp` and `stl` write the Mesh alone (Gmsh, Abaqus/CalculiX, an STL skin).\n`inp` preserves exact Set labels with Abaqus quoting; an unsupported label or heading\nreturns `export.unavailable`. It writes no Materials, Constraints, Loads or Steps."
        return await self._call("dispatch", MeshExportArgs(format=format, step=step).wire())

    async def constraint_fix(self, *, name: str, on: str, dofs: Any = OMIT) -> Any:
        "Fix degrees of freedom to zero on a Set (default: all displacement components, a\nclamped support). A fix that holds all three displacements and names no rotation is a\nclamp: on a beam joint it holds the three rotations rx, ry, rz as well, so a beam's\nfixed end is what `constraint.fix` without `dofs` means. For a pinned beam support use\nconstraint.pin; for a roller give only the normal component; name rx, ry or rz to hold\na rotation on its own. Rotations are inert on every node that is not a beam joint.\nFixing every node of a Body makes the solve trivial; fix faces, not bodies."
        return await self._call("dispatch", ConstraintFixArgs(name=name, on=on, dofs=dofs).wire())

    async def constraint_pin(self, *, name: str, on: str) -> Any:
        "Pin a Set: fix its three displacements and leave every rotation free. On a beam joint\nthis is the pinned support of a simply supported beam or a portal frame's base hinge;\nthe only difference from constraint.fix is the rotational restraint. On a solid's\nnodes it is the same as constraint.fix, because those carry no rotation."
        return await self._call("dispatch", ConstraintPinArgs(name=name, on=on).wire())

    async def constraint_prescribe(self, *, name: str, on: str, dof: Any, value: Any) -> Any:
        "Prescribe a non-zero displacement of one component on a Set, for example a settlement\nof \"2 mm\" in uy. Reactions on prescribed Sets are reported like any other constraint."
        return await self._call("dispatch", ConstraintPrescribeArgs(name=name, on=on, dof=dof, value=value).wire())

    async def constraint_symmetry(self, *, name: str, on: str, normal: Any) -> Any:
        "Symmetry plane: fixes the displacement component along `normal` on the Set (the cut\nface of a half or quarter model), and on beam joints the two rotations about the axes\nin the plane. Model a half and say so in the report; loads on the symmetry plane\nitself must be halved by you."
        return await self._call("dispatch", ConstraintSymmetryArgs(name=name, on=on, normal=normal).wire())

    async def constraint_temperature(self, *, name: str, on: str, value: Any) -> Any:
        "Hold a Set at a fixed temperature in a heat Step (the Dirichlet boundary of conduction).\nA heat Step needs either one of these or a convection boundary, or the temperature is\nonly defined up to a constant and the solve is singular. In a transient Step the value is\nmultiplied by the Step's `amplitude`, so \"100 K\" with a sine amplitude is a driven end."
        return await self._call("dispatch", ConstraintTemperatureArgs(name=name, on=on, value=value).wire())

    async def contact_add(self, *, name: str, master: str, slave: str, kind: Any, tol: Any = OMIT) -> Any:
        "Connect two face Sets. `bonded` ties them so the parts behave as one: every node of\n`slave` is constrained to the point it projects onto in `master`, in every displacement\ncomponent. It is a linear constraint inside the same operator — no iteration, no gap\nopening, no sliding — so a bonded assembly costs a static solve, not a contact search.\n`tol` is then the largest gap that still pairs, defaulting to 1e-4 of the Mesh diagonal;\na node further from the master than that is `contact.unpaired`. In a heat Step a bonded\ntie carries temperature, so the two parts are in perfect thermal contact.\n`frictionless` lets the faces press, open and slide: `tol` is then the *search distance*\n(same default), every slave node within it is paired and its initial gap along the master\nnormal recorded (positive when open, so faces may start apart and close under load), and\nthe solve keeps a node on the master surface only while the normal force there is\ncompressive. A node beyond `tol` is simply not a candidate. Hold each Body against the\nmotions the contact cannot stop: a frictionless face transmits no tangential force, so a\npart held only by it can still slide. The Result carries a `contactPressure` field on the\nslave nodes and query.result lists every frictionless pair with its active fraction and\nthe resultant it carries; a pair that ends fully open is a `contact.open` warning, a part\nthat lifts off entirely with nothing else holding it a `contact.open` error, and a set\nthat never settles a `contact.chatter` error naming the nodes. Put the *finer* mesh on\nthe slave side either way: a node-to-face constraint passes the patch test that way\nround. A contact is listed in a Step's `constraints` like any other, and is removed with\nconstraint.remove. Contacts add stiffness between Bodies that share no element, which\nquery.cost does not count."
        return await self._call("dispatch", ContactAddArgs(name=name, master=master, slave=slave, kind=kind, tol=tol).wire())

    async def constraint_cyclic(self, *, name: str, from_: str, to: str, axis: Any, angle_deg: float, through: Any = OMIT, tol: Any = OMIT) -> Any:
        "Tie two sector faces related by a rotation: u(to) = R·u(from), with R the rotation of\n`angleDeg` about `axis` through `through` (default the origin). This is the zero-harmonic\ncondition: a static solve is exact for loading that repeats sector by sector, and a modal\nStep finds only the harmonic-index-0 family. Non-zero harmonics need a complex\neigenproblem and are not implemented. The two faces must mesh identically — use the\nrevolve mesher, whose `<body>.theta0` and `<body>.theta1` Sets are what this Command is\nfor. The tie is node to node, not node to face, because a matching sector mesh is the\nonly case in scope. Because the coefficients are a rotation rather than a partition of\nunity, a cyclic model's global reaction sum is not the applied load — read\nquery.result's per-Constraint reactions, never its balance, on a Step that lists this\nCommand. Refused in an explicit Step, like a bonded contact."
        return await self._call("dispatch", ConstraintCyclicArgs(name=name, from_=from_, to=to, axis=axis, angle_deg=angle_deg, through=through, tol=tol).wire())

    async def constraint_couple(self, *, name: str, point: str, on: str, kind: Any) -> Any:
        "Connect a point mass (geometry.addMass) to a face Set, the way a bolt, a bearing or a\nload introduction is idealised. `distributed` makes the point follow the face's weighted\nmean displacement and adds no stiffness at all, so a force at the point spreads over the\nface in exactly the weights a uniform traction would produce, and a mass at the point\nloads the face the same way; that is the one to reach for. `rigid` is the opposite:\nevery node of the face takes the point's displacement, so the face cannot deform and the\npart around it is stiffer than the real one. Nodes carry translations only, so **neither\nkind transmits a moment**: a couple cannot be applied at the point, and a rigid coupling\ndoes not rotate its face — it translates it. It is a linear multipoint constraint inside\nthe same operator, needs no iteration, is listed in a Step's `constraints` like any\nother Constraint, and is removed with constraint.remove."
        return await self._call("dispatch", ConstraintCoupleArgs(name=name, point=point, on=on, kind=kind).wire())

    async def constraint_remove(self, *, name: str) -> Any:
        "Remove a Constraint. Fails with in-use if a Step still lists it; re-issue step.add without\nit first. Removing a constraint makes existing Results of that Step stale."
        return await self._call("dispatch", ConstraintRemoveArgs(name=name).wire())

    async def load_pressure(self, *, name: str, on: str, value: Any) -> Any:
        "Uniform pressure on a face Set, positive into the surface (a negative value pulls).\nPressure times query.set.pressureArea is a scalar integral; it is not the net vector\nforce on a curved Set. The loaded area includes thickness or axisymmetric weighting.\nShell pressureArea measures the original midsurface; physical curved shell face loads\ninclude the Section's top/bottom offsets."
        return await self._call("dispatch", LoadPressureArgs(name=name, on=on, value=value).wire())

    async def load_traction(self, *, name: str, on: str, total: Any) -> Any:
        "A total force vector spread uniformly over a face Set's area (\"10 kN downward on this\nface\"). Use this instead of nodal forces on solids: point loads give singular stresses."
        return await self._call("dispatch", LoadTractionArgs(name=name, on=on, total=total).wire())

    async def load_force(self, *, name: str, on: str, total: Any) -> Any:
        "A total force split equally over the nodes of a node Set. Point loads on solids give\nsingular stresses near the node; prefer load.traction on a face unless you mean a point."
        return await self._call("dispatch", LoadForceArgs(name=name, on=on, total=total).wire())

    async def load_moment(self, *, name: str, on: str, total: Any) -> Any:
        "A concentrated moment, as a total vector about the global axes, split equally over the\nnodes of a node Set. It acts on the rotational degrees of freedom, which only the\njoints of beam Bodies have: on any other node it has nothing to act on and the Step\nfails with model.ill-posed naming the Load. Right-handed about each axis, in the\nModel's torque unit (\"5 kN m\")."
        return await self._call("dispatch", LoadMomentArgs(name=name, on=on, total=total).wire())

    async def load_gravity(self, *, name: str, g: Any) -> Any:
        "Gravity (or any uniform acceleration) as a body force on every Body whose Material has\na density; Bodies without one are skipped and listed in the warnings. Explicit Steps\napply gravity with their lumped inertia (m_i g); static Steps use consistent body forces."
        return await self._call("dispatch", LoadGravityArgs(name=name, g=g).wire())

    async def load_temperature(self, *, name: str, bodies: Any, value: Any, reference: Any = OMIT) -> Any:
        "A uniform temperature on the listed Bodies relative to `reference` (default 293.15 K),\nproducing thermal strain α·ΔT in a static Step. Needs `alpha` on the Material.\nTargets may be explicit geometry or the Body defined by a mapped or swept mapped mesher.\nDisjoint Bodies compose independently, each using its own reference. Overlapping\nassignments must produce exactly the same increment; otherwise `solve.run` returns\n`model.ill-posed` naming both Loads and the Body. Equal increments are not added.\nWhen continuing a heat Step, its nodal temperatures replace `value`; these per-Body\nreferences still apply, with 293.15 K on Bodies without a temperature Load."
        return await self._call("dispatch", LoadTemperatureArgs(name=name, bodies=bodies, value=value, reference=reference).wire())

    async def load_convection(self, *, name: str, on: str, h: Any, t_inf: Any) -> Any:
        "Newton cooling on a face Set: heat `h (T − tInf)` leaves the surface per unit area. This\nis the usual \"exposed to air\" boundary and, unlike a flux, it also stiffens the system,\nso a heat Step with a convection face needs no fixed temperature to be well posed."
        return await self._call("dispatch", LoadConvectionArgs(name=name, on=on, h=h, t_inf=t_inf).wire())

    async def load_heat_flux(self, *, name: str, on: str, q: Any) -> Any:
        "A prescribed heat flux into a face Set, in W/m² (negative flows outward). An insulated\nface needs no Command at all: zero flux is what a face with no boundary condition does."
        return await self._call("dispatch", LoadHeatFluxArgs(name=name, on=on, q=q).wire())

    async def load_radiation(self, *, name: str, on: str, emissivity: float, t_inf: Any) -> Any:
        "Grey-body radiation from a face Set to a large surrounding at `tInf`: the surface loses\n`sigma * emissivity * (T^4 - tInf^4)` per unit area, with the Stefan-Boltzmann constant\nsigma = 5.670374419e-8 W/(m^2 K^4) built in. Both temperatures are absolute, so a Model\ndisplayed in degC is converted to kelvin before the fourth power is taken. `emissivity`\nis dimensionless and must lie in (0, 1]; 1 is a black body. Like a convection face this\nholds the temperature, so a heat Step whose only boundary is radiation is still well\nposed. Radiation makes a heat Step nonlinear: it is solved by repeated assembly and\nsolution, governed by step.add's nonlinearTolerance and nonlinearMaxIterations. A\nheat-steady Result reports the number of passes as its solver iteration count, and a Step\nthat runs out of them fails with solve.diverged rather than returning a wrong answer."
        return await self._call("dispatch", LoadRadiationArgs(name=name, on=on, emissivity=emissivity, t_inf=t_inf).wire())

    async def load_heat_source(self, *, name: str, bodies: Any, q: Any) -> Any:
        "A volumetric heat source on whole Bodies, in W/m³ (ohmic heating, hydration, a reaction).\nIt is a density, not a total: the heat delivered is `q` times each Body's volume.\nTargets may be explicit geometry or the Body defined by a mapped or swept mapped mesher;\nfor a plane-stress Sheet, the volume includes its specified thickness."
        return await self._call("dispatch", LoadHeatSourceArgs(name=name, bodies=bodies, q=q).wire())

    async def load_torque(self, *, name: str, on: str, total: Any) -> Any:
        "A torsional load on a face Set of an axisymmetric Model with twist: a circumferential\ntraction `t_theta = c r` at every Gauss point, with `c` chosen so the net torque about\nthe axis equals `total` exactly, curved faces included. Outside the axisymmetric\nidealisation with twist this is `unsupported`; enable it with model.setIdealisation."
        return await self._call("dispatch", LoadTorqueArgs(name=name, on=on, total=total).wire())

    async def contact_thermal(self, *, name: str, of: str, conductance: Any) -> Any:
        "A finite conductance across a bonded pair: heat h_c·(T_slave − T_master) crosses the\ninterface per unit area, so the two sides are no longer at the same temperature.\nAssembled into the heat operator exactly as load.convection is, except that it couples\ntwo temperature fields instead of one field to tInf. Naming a contact here replaces its\nperfect thermal tie; the mechanical tie is unaffected."
        return await self._call("dispatch", ContactThermalArgs(name=name, of=of, conductance=conductance).wire())

    async def load_remove(self, *, name: str) -> Any:
        "Remove a Load. Fails with in-use if a Step still lists it; re-issue step.add without it\nfirst. Removing a load makes existing Results of that Step stale."
        return await self._call("dispatch", LoadRemoveArgs(name=name).wire())

    async def step_add(self, *, name: str, procedure: Any, constraints: Any, loads: Any, output: Any = OMIT, after: Any = OMIT, n_modes: Any = OMIT, shift: Any = OMIT, dt: Any = OMIT, t_end: Any = OMIT, theta: Any = OMIT, output_every: Any = OMIT, dt_factor: Any = OMIT, amplitude: Any = OMIT, initial: Any = OMIT, alpha: Any = OMIT, rayleigh_alpha: Any = OMIT, rayleigh_beta: Any = OMIT, initial_velocity: Any = OMIT, increments: Any = OMIT, max_cutbacks: Any = OMIT, nonlinear_tolerance: Any = OMIT, nonlinear_max_iterations: Any = OMIT, f_start: Any = OMIT, f_stop: Any = OMIT, points: Any = OMIT, sweep: Any = OMIT, damping_ratio: Any = OMIT, damping_ratios: Any = OMIT, psd: Any = OMIT) -> Any:
        "Define an analysis Step: the procedure, and which Constraints and Loads are active in\nit. `output` lists the fields to compute (default displacement, stress, von Mises and\nreactions). Steps run in the order given by step.reorder, and `after` names an earlier\nStep whose Result this one continues — a static Step after a heat Step picks up its\ntemperature field and turns it into thermal stress, and a modal Step after a static one\npicks up its stress state and becomes a prestressed (stress-stiffened) modal analysis,\nwhich is what a tensioned or preloaded member needs. The remaining fields belong to one\nprocedure each and are ignored by the others. Each field declares `x-procedures` in the\nschema (`*` means common to every procedure), so hosts can present the selected procedure\nwithout discarding values when it changes. The Procedure enum declares material inputs\nand result outputs for humans and AI tools. Field ownership: `nModes` and `shift` to modal, `nModes`\nalone (default 1) to buckling, `dt`,\n`tEnd`, `theta`, `initial`, `amplitude` and `outputEvery` to heat-transient, `tEnd`,\n`dtFactor`, `initialVelocity` and `outputEvery` to explicit, `dt`, `tEnd`, `alpha`,\n`rayleighAlpha`, `rayleighBeta`, `initialVelocity`, `amplitude` and `outputEvery` to\nimplicit, `fStart`, `fStop`, `points`, `sweep`, `dampingRatio`, `dampingRatios`,\n`rayleighAlpha`, `rayleighBeta` and `outputEvery` to harmonic, `amplitude`, `dt`, `tEnd` and\n`outputEvery` to static as well, and `increments`, `maxCutbacks`, `tEnd` and\n`amplitude` to static-nonlinear. An\nimplicit Step integrates `M a + C v + K u = f` by HHT-α with `alpha` in [-1/3, 0]\n(default 0, Newmark average acceleration: second order, unconditionally stable and\nenergy-conserving; -0.05 adds numerical damping of the mesh-frequency ringing) and\nRayleigh damping `C = rayleighAlpha·M + rayleighBeta·K` (both default 0; a modal\ndamping ratio ζ at circular frequency ω is `rayleighAlpha/(2ω) + rayleighBeta·ω/2`).\nIts `amplitude` scales the Loads only and is refused with a non-zero prescribed\ndisplacement; its initial acceleration is solved from the loads at t = 0, so a suddenly\napplied load is exactly that. Its reactions include the inertia and damping forces and\nits applied totals are the d'Alembert force `f - M a - C v`, so the balance closes; the\nscalars `load_total_*` keep the plain load. An `amplitude` on a static Step ramps its Loads and\nprescribed displacements over increments from 0 to `tEnd` (default \"1 s\", with `dt`\ndefaulting to the whole of it, so a table written in step fraction works unchanged) and\nkeeps every `outputEvery`-th increment as a retained frame; a temperature Load is never\nscaled, so its thermal strain is present in full at every increment. Without an\n`amplitude` a static Step is the single solve it has always been and retains nothing.\nA static-nonlinear Step always steps, over `increments` equal pieces of the same\npseudo-time, and keeps every converged one.\nHeat-steady requires a finite positive material conductivity `k`; heat-transient also\nrequires finite positive `rho` and `cp`, and its `theta` must lie in [0, 1].\n`query.model` checks each Step's active Constraints/Loads and assigned Materials:\nstatic, static-nonlinear and buckling need mechanical supports; steady heat needs a\nprescribed temperature or an ambient convection/radiation boundary. Free-free modal\nand unconstrained dynamics are valid, and transient heat may be insulated. These\npre-mesh warnings identify missing inputs; only the resolved solve can establish that\nevery connected component is restrained and every selected Set contains nodes.\nStep-specific warnings carry their exact `step` identity separately from the display\nlocation in `where`, so hosts can scope blockers without parsing names or prose.\n`nonlinearTolerance` and `nonlinearMaxIterations` govern any Step whose system depends\non its own answer — a radiation load, or geometric nonlinearity — and are ignored by a\nStep that is linear.\nHeat Results report net applied power, positive removed heat and stored-energy rate;\ntransient powers belong to the last θ-method integration stage (radiation uses weighted\nendpoint fluxes), while temperature fields belong to its endpoint.\nA modal Step's `after` is optional and means stress stiffening: naming a solved\n`static` or `static-nonlinear` Step adds that state's geometric stiffness to K, so the\nfrequencies are those of the *preloaded* structure (tension up, compression down, zero\nat the buckling load), and `prestressFrom` on the Result names the preload Step. Naming\na heat Step instead keeps the existing meaning, the temperature field alone, and\nstiffens nothing.\nA harmonic Step requires `after` to name a Step whose `modal` Result is current: it\nsuperposes those mode shapes rather than solving anything (ADR 0020), so its accuracy is\nbounded by that Step's `nModes`. It drives its own Loads at each swept frequency and\nanswers a nodal amplitude and a phase lag per retained frequency; `displacement` is the\namplitude at the frequency of peak response. Its Constraints may only hold DOFs at zero\n— a moving support is base excitation, which this procedure does not do."
        return await self._call("dispatch", StepAddArgs(name=name, procedure=procedure, constraints=constraints, loads=loads, output=output, after=after, n_modes=n_modes, shift=shift, dt=dt, t_end=t_end, theta=theta, output_every=output_every, dt_factor=dt_factor, amplitude=amplitude, initial=initial, alpha=alpha, rayleigh_alpha=rayleigh_alpha, rayleigh_beta=rayleigh_beta, initial_velocity=initial_velocity, increments=increments, max_cutbacks=max_cutbacks, nonlinear_tolerance=nonlinear_tolerance, nonlinear_max_iterations=nonlinear_max_iterations, f_start=f_start, f_stop=f_stop, points=points, sweep=sweep, damping_ratio=damping_ratio, damping_ratios=damping_ratios, psd=psd).wire())

    async def step_remove(self, *, name: str) -> Any:
        "Remove a Step and the Result it produced, if any. Constraints and Loads it referenced\nstay in the Model and can be reused by other Steps. Fails with `in-use` while another\nStep names it in `after`; re-issue that dependent Step without the reference first."
        return await self._call("dispatch", StepRemoveArgs(name=name).wire())

    async def step_reorder(self, *, order: Any) -> Any:
        "Set the run order of Steps; `order` must list every Step name exactly once and keep each\nStep after the prerequisite named by its `after` field. Steps run in this order and a\nlater Step may inherit state (a temperature field) from an earlier one."
        return await self._call("dispatch", StepReorderArgs(order=order).wire())

    async def solve_run(self, *, step: str, solver: Any = OMIT, tolerance: Any = OMIT, max_iterations: Any = OMIT) -> Any:
        "Run a Step. Checks well-posedness first (materials, constraints, rigid-body modes,\nelement quality) and refuses with a suggested fix. Returns extremes, reactions and every\nomitted optional material property the successful solver actually read as zero; always\ncheck that reactions balance the applied loads before trusting a stress. A Step with\n`after` requires its predecessor's Result to match the current Model state; after an edit,\nsolve the predecessor again before continuing the chain.\nDirect linear solves verify their residual too: nonfinite or excessive residuals return\nsolve.stalled instead of storing a Result. Static and non-radiating steady direct solves use `tolerance`\n(default 1e-10) with the same 100-fold f64 roundoff allowance as iterative refinement. The\ndirect tolerance must be positive and its 100-fold allowance finite, or a schema error is returned.\nModal solves verify every requested eigenpair's normwise backward residual against\n`tolerance` and return solve.stalled without storing a Result when `maxIterations`\nsubspace sweeps are exhausted. The reported residual is the largest requested-pair\nresidual; it certifies algebraic backward accuracy, not frequency or mesh accuracy.\nResolved Ritz values must also stabilize to relative change 1e-10. Values unresolved\nat the per-mode Rayleigh-contraction roundoff scale carry modal.unresolved-frequency\nwarnings; their backward residual passed, but relative frequency convergence is not certified.\nOn Windows, direct numeric factorization is sequential to avoid a verified faer defect;\nassembly and triangular solves retain the engine thread count."
        return await self._call("dispatch", SolveRunArgs(step=step, solver=solver, tolerance=tolerance, max_iterations=max_iterations).wire())

    async def study_converge(self, *, step: str, sizes: Any, quantity: Any, restore: Any = OMIT) -> Any:
        "Re-mesh at each size, re-solve the Step and report the quantity of interest per size,\nthe observed convergence rate and a Richardson estimate of the converged value. Sizes\nmay have unequal refinement ratios. Three distinct positive sizes are needed for a\nfinite limit of the form q(h) = q* + C h^p with p > 0; otherwise the estimate and rate\nare unavailable. Restores the previous mesh settings afterwards unless `restore` is false.\nUses the Step's actual procedure: static and steady heat measure equilibrium fields;\ntransient heat and explicit dynamics measure the final field at the configured tEnd\nwith the Step's time settings unchanged. Modal Steps are unsupported because a mode\namplitude is not a mesh-independent quantity; compare frequencies with\nsolve.run/query.result instead. Steps with after are unsupported: solve their\ndependencies and target at each mesh explicitly."
        return await self._call("dispatch", StudyConvergeArgs(step=step, sizes=sizes, quantity=quantity, restore=restore).wire())

    async def study_adapt(self, *, step: str, target_error: float, max_iterations: Any = OMIT, max_elements: Any = OMIT, marking_fraction: Any = OMIT, refinements: Any = OMIT) -> Any:
        "Solve, estimate local spatial error with ZZ recovery, refine the largest\ncontributions, and repeat until targetError or maxIterations is reached.\nLeaves the last solved mesh and Result installed. Supports planar tri3/solid\ntet4 with static, heat-steady or heat-transient Steps without after. Transient\nruns restart at the configured initial state and estimate the final field;\nthis does not estimate time error or adapt/coarsen within a time integration.\nerrorEstimate is a dimensionless element field; its squared sum is the squared\nglobal relative estimate. Recovery is an indicator, not a certified error bound.\nRefines the existing boundary approximation without CAD projection. Exceeding\nmaxElements or cancellation rolls back the entire Command."
        return await self._call("dispatch", StudyAdaptArgs(step=step, target_error=target_error, max_iterations=max_iterations, max_elements=max_elements, marking_fraction=marking_fraction, refinements=refinements).wire())

    async def journal_undo(self, *, steps: Any = OMIT, expected_journal: Any = OMIT) -> Any:
        "Undo the last `steps` Commands (default 1), restoring the Model and orphaning any\nResult produced after that point. Not recorded in the Journal. If `expectedJournal` is\nsupplied, it must equal the complete-history `hash` from `query.journal` at execution time; otherwise\nnothing is undone. Use this guard for a saved turn boundary while other callers can edit."
        return await self._call("dispatch", JournalUndoArgs(steps=steps, expected_journal=expected_journal).wire())

    async def journal_redo(self, *, steps: Any = OMIT) -> Any:
        "Redo the last `steps` undone Commands (default 1) by re-applying them; a redone solve\nre-solves. Not recorded in the Journal; any new Command after an undo clears the redo stack."
        return await self._call("dispatch", JournalRedoArgs(steps=steps).wire())

    async def plugin_load(self, *, name: str, kind: Any, language: Any, source: Any, manifest: Any = OMIT) -> Any:
        "Load a Plugin filling one Extension Point (a material law, element, load, post\nquantity, mesher or procedure) in TypeScript, WGSL or wasm; recorded in the Journal by\ncontent hash. Not available yet: returns unsupported until the plugin phase lands."
        return await self._call("dispatch", PluginLoadArgs(name=name, kind=kind, language=language, source=source, manifest=manifest).wire())

    async def query_portable_project(self) -> Any:
        "Lossless portable project snapshot, including all retained solved meshes and f64 fields.\nHost storage is separate; capture the checked ReadReply stamp with this owned value."
        return await self._call("query", QueryPortableProjectArgs().wire())

    async def query_model(self) -> Any:
        "Everything about the Model in one read: bodies with volumes and materials, imported\nface patches with paste-ready naming predicates, named Sets, constraints, loads with\ntheir totals, steps and predecessor links, mesh settings, and the well-posedness warnings\nthat would block a solve. Material properties include thermal expansion `alpha` in 1/K,\nconductivity `k` in W/(m K), specific heat `cp` in J/(kg K), and the supplied `source`.\nExpansion and conductivity preserve one isotropic value or three material-axis values.\nRead this before changing anything."
        return await self._call("query", QueryModelArgs().wire())

    async def query_document(self) -> Any:
        "The complete authoritative Model file and Journal in SI, with the real Model hash and\nrevision. Retains selected display-unit strings without formatting a display summary;\nuse this to save even when query.model reports unit.display. This read changes neither\nthe Model nor retained Results. Hosts apply their exact UTF-8 save encoder and byte limit\nbefore writing; this Query performs no I/O or replacement validation."
        return await self._call("query", QueryDocumentArgs().wire())

    async def query_definition(self, *, kind: Any, name: str) -> Any:
        "The complete upsert Command for an existing object's current definition, with exact\nSI quantities. Use it to populate an edit form; change its arguments and dispatch it\nto apply. Display summaries are rounded and must never be used to reconstruct edits.\nAuto-generated Sets and mesher-owned Bodies have no editable object definition."
        return await self._call("query", QueryDefinitionArgs(kind=kind, name=name).wire())

    async def query_mesh(self) -> Any:
        "Counts and sanity of the current Mesh (nodes, elements, element kind, DOF, bounding box,\nedge lengths, Sets with their resolved sizes, quality). Builds the Mesh if needed."
        return await self._call("query", QueryMeshArgs().wire())

    async def query_set(self, *, name: str) -> Any:
        "What a Set resolved to on the current Mesh: kind, count, bounding box, geometric measure\nand corner-node centroid. Solid volumes integrate every original shape node, including\nTet10/Hex20 midside nodes: tetrahedron degree3 and tensor degree5 per coordinate are\nsufficient for their Jacobian determinants, up to f64 roundoff. Surface areas and edge\nlengths use original tangents. Linear triangles and lines are exact up to roundoff;\nbilinear faces use Gauss2. Curved norms are numerical, using Gauss3 for Quad8/Line3\nand symmetric triangle degree5 for Tri6.\nCurved area/length accuracy improves under refinement; no corner skin is substituted.\nFace Sets also report pressureArea from the load boundary quadrature,\nincluding thickness or radial weighting (plane strain: one metre of depth). Pressure\ntimes pressureArea is a scalar integral, not a net vector force. Shell pressureArea is\nthe original midsurface area without requiring Material/Section; curved physical shell\nloads use the Section's top/bottom offsets. Builds the Mesh if needed.\nThe centroid averages resolved node coordinates; authored imported NSETs include\nunused source labels. A bounded fixed-order fallback prevents a finite coordinate\nmean overflowing through rounding, while preserving existing finite mean results."
        return await self._call("query", QuerySetArgs(name=name).wire())

    async def query_result(self, *, result_id: Any = OMIT, step: Any = OMIT) -> Any:
        "Summary of a Step's Result: solver info, extremes of every field with their location,\nreactions per constraint, applied totals, solver-used omitted material assumptions, and\nwhether the Result is stale (the Model changed after it was solved). Check the reaction\nbalance and assumptions first."
        return await self._call("query", QueryResultArgs(result_id=result_id, step=step).wire())

    async def query_results(self) -> Any:
        "Catalogue of the eight most recent successful solve instances, oldest first. Reads do\nnot extend retention. Evicted ids are unavailable; Model import/new clears records."
        return await self._call("query", QueryResultsArgs().wire())

    async def query_surface(self, *, step: Any = OMIT, result_id: Any = OMIT) -> Any:
        "The triangulated boundary of a retained Result's solved Mesh, with f64 SI positions,\noriginal node indices, Body identities and face-Set memberships. Explicit resultId\nreads that immutable solve even after Model edits; an omitted id selects the latest\ncompatible Result for step (or the last solved Step), rejecting stale or missing Results.\nThis never substitutes the current Mesh or a geometry preview. Use query.results for ids."
        return await self._call("query", QuerySurfaceArgs(step=step, result_id=result_id).wire())

    async def query_field(self, *, step: Any = OMIT, result_id: Any = OMIT, field: str) -> Any:
        "A final field in SI with explicit entity layout, selected by solve instance or the current per-Step default.\nField names include mode:k for one-based modal/buckling shapes owned by the Result\n(`1 <= k <= query.result.modeCount`) and stressPly:k:bottom/top\nfor laminate ply faces (k starts at 1, bottom to top within each Section). Ply stresses\nare global xx, yy, zz, xy, xz, yz in Pa, unaveraged per element node; elements without\nthat ply carry zeros. Both sides of an interface remain distinct. Explicit ids use solved metadata;\nomitted ids refuse stale Results. Retained samples use query.frame's existing protocol."
        return await self._call("query", QueryFieldArgs(step=step, result_id=result_id, field=field).wire())

    async def query_difference(self, *, left: Any, right: Any, onto: Any) -> Any:
        "Subtract two explicitly retained nodal fields as `left - right` on either Result's\nMesh. Unequal meshes use finite-element interpolation and report uncovered nodes as\nnull values; nonfinite arithmetic is a structured error. No current Result, display\nconversion, or node-number pairing is implied. Each operand may independently select\na retained primary frame with the existing exact/nearest FrameSample protocol; resolved\nindices and physical times are returned. Historical derived fields are unavailable.\nOmitted samples preserve final-field comparison. There is no temporal interpolation."
        return await self._call("query", QueryDifferenceArgs(left=left, right=right, onto=onto).wire())

    async def query_frames(self, *, result_id: Any = OMIT, step: Any = OMIT) -> Any:
        "Catalogue of retained primary-field frames for heat-transient, explicit or amplitude-driven static Steps (default: last solved Step).\nIndex 0 is the initial state; indices count retained frames, not integration steps.\nMetadata remains available for stale Results. No nodal values are copied by this Query."
        return await self._call("query", QueryFramesArgs(result_id=result_id, step=step).wire())

    async def query_frame(self, *, result_id: Any = OMIT, step: Any = OMIT, index: Any = OMIT, sample: Any = OMIT, field: Any = OMIT) -> Any:
        "One retained primary field from a heat-transient, explicit or amplitude-driven static Step. Supply exactly one of zero-based retained index\nor sample (retained index / physical time with exact or nearest selection). Time\nselection uses the same roundoff tolerance, earlier-tie rule and no-extrapolation\npolicy as sampled probe/path. Values are SI,\ncomponent-fastest, with three components per node, matching final FieldData: a 2D\ndisplacement has zero z; temperature occupies x with zero y/z. Defaults to the retained\nprimary field. Derived fields were not retained and are refused. Omitted resultId refuses result.stale."
        return await self._call("query", QueryFrameArgs(result_id=result_id, step=step, index=index, sample=sample, field=field).wire())

    async def query_probe(self, *, result_id: Any = OMIT, step: Any = OMIT, field: Any, component: Any = OMIT, sample: Any = OMIT, at: Any) -> Any:
        "A field value at a point (default: the last solved Step). Nodal fields are\ninterpolated; errorEstimate returns the containing element's constant value\nwith interpolated=false. Shared-face ties use the lowest element id. Component\nindices: displacement 0..3, stress Voigt 0..6 (xx, yy, zz, xy, xz, yz), principal 0..3.\nOptional sample selects a retained primary-field frame; omitted means the final field.\nOmitted resultId refuses `result.stale` after edits; an explicit id uses its solved Mesh."
        return await self._call("query", QueryProbeArgs(result_id=result_id, step=step, field=field, component=component, sample=sample, at=at).wire())

    async def query_path(self, *, result_id: Any = OMIT, step: Any = OMIT, field: Any, component: Any = OMIT, sample: Any = OMIT, from_: Any, to: Any, n: int) -> Any:
        "A field sampled at `n` points along the line from `from` to `to`, for a line plot.\nOptional sample selects a retained primary-field frame; omitted means the final field.\nOmitted resultId refuses `result.stale` after edits; an explicit id uses its solved Mesh."
        return await self._call("query", QueryPathArgs(result_id=result_id, step=step, field=field, component=component, sample=sample, from_=from_, to=to, n=n).wire())

    async def query_cost(self, *, step: str) -> Any:
        "Cost before solving: DOF, matrix non-zero bounds, exact retained-frame schedule and\ncounted peak memory. Counting uses at most 16 MiB scratch after meshing. Feasibility is\nfalse above a fixed 1.5 GiB planning budget, otherwise unknown because solver fill,\nallocator overhead and host serialization are excluded.\nUse before large solves; this query does not promise that a solve fits the current host."
        return await self._call("query", QueryCostArgs(step=step).wire())

    async def query_journal(self, *, from_seq: Any = OMIT) -> Any:
        "The Journal: every applied Command with the Model hash after it, and whether undo or\nredo is possible. `fromSeq` returns only entries at or after that sequence number."
        return await self._call("query", QueryJournalArgs(from_seq=from_seq).wire())

    async def query_journal_diff(self, *, base: Any) -> Any:
        "Compare this Model's Journal with a supplied base Journal. Returns the shared causal\nprefix and each ordered divergent tail: removed entries belong to `base`, added entries\nto the current Journal. Entry identity is the typed Command plus `hashAfter`; `seq` is\nonly a displayed location and is ignored. Entries after the first divergence are not\nre-aligned. This read never replays either Journal."
        return await self._call("query", QueryJournalDiffArgs(base=base).wire())

    async def query_script(self) -> Any:
        "The Journal as a TypeScript script against the `fem` API that reproduces the Model line by\nline; what the Script panel shows and what script.run accepts back."
        return await self._call("query", QueryScriptArgs().wire())

    async def query_convert(self, *, quantity: Any, to: str) -> Any:
        "Convert a quantity to another unit of the same dimension (\"2 MPa\" to \"psi\"); an error\nnames the dimensions when they differ. Handy for checking inputs before using them.\nRejects nonfinite values and nonzero scaling that rounds to zero, including input\nscaling before adding a temperature offset. Surviving subnormals, ordinary f64\nrounding and affine zeros (273.15 K to 0 degC) remain valid."
        return await self._call("query", QueryConvertArgs(quantity=quantity, to=to).wire())

    async def query_abaqus_dependencies(self, *, text: str, source_name: Any = OMIT, source_files: Any = OMIT) -> Any:
        "Inspect the supplied Abaqus bundle for missing INCLUDE and NODE/ELEMENT INPUT files.\nUses the same bounded lexer and safe relative-path graph as conversion. This read\nperforms no model/physics conversion or file/network I/O; hosts can acquire listed\nfiles through their captured scoped I/O and repeat until the bundle is complete.\nThe actual conversion still rejects missing files and never publishes partial data."
        return await self._call("query", QueryAbaqusDependenciesArgs(text=text, source_name=source_name, source_files=source_files).wire())

    async def query_convert_abaqus(self, *, text: str, name: str, body: str, mode: Any, unit_length: Any, unit_force: Any = OMIT, unit_time: Any = OMIT, source_name: Any = OMIT, source_files: Any = OMIT, sha256: str) -> Any:
        "Convert a bounded Abaqus text deck to checked portable Commands without mutating\nthe active Model or solving. Explicit positive unitLength and static-mode unitForce\ndefine source units; coordinates/displacements scale by L, forces by F and stress\nby F/L². Structural instances, labels, exact Sets and surfaces are normalized by\nthe typed deck reader. The report records all translated analysis Steps and notes\nrecognized requests whose output/increment execution differs from FEM Lab.\nStatic mode imports constant isotropic materials and exact nonoverlapping solid\nsection regions covering every element, direct or solid symbolic BOUNDARY,\nCLOAD and uniform DLOAD Pn / DSLOAD P pressure. Multiple small-displacement static\nSteps retain effective inherited loads/supports; OP=NEW resets that family's state,\nOP=MOD updates it. Conflicting repeated definitions within one Step fail explicitly.\nEach Step configures its final linear equilibrium, without source increment history.\nUnsupported physics/formulations/parameters fail rather than being discarded.\nMesh mode configures no analysis. Neither mode infers missing physical units.\nInput and serialized response are bounded to 16 MiB; hosts must privately prepare\nall returned Commands through Candidate and publish one validated replacement."
        return await self._call("query", QueryConvertAbaqusArgs(text=text, name=name, body=body, mode=mode, unit_length=unit_length, unit_force=unit_force, unit_time=unit_time, source_name=source_name, source_files=source_files, sha256=sha256).wire())

    async def query_material_library(self, *, name: Any = OMIT) -> Any:
        "Primary-source material data with dimensions, grade, condition, temperature and a source\nfor every reported property. With no `name`, lists the stable catalogue. With a canonical\nid, name or unambiguous alias, returns that entry. Missing properties are explicit nulls:\nnever infer them before material.add. Copy the entry's `materialAddSource` into that\nCommand's `source` so the Journal preserves provenance."
        return await self._call("query", QueryMaterialLibraryArgs(name=name).wire())

    async def query_objects(self, *, kinds: Any = OMIT) -> Any:
        "Every nameable thing in the Model as `@`-mention references (`body:beam`, `set:beam.top`,\n`material:steel`, `journal:12`), with a one-line summary each; the mention picker's index."
        return await self._call("query", QueryObjectsArgs(kinds=kinds).wire())

    async def query_report(self, *, step: Any = OMIT, include: Any = OMIT) -> Any:
        "The whole analysis as one Markdown calculation note: assumptions, geometry, materials,\nmesh and quality, loads with totals, results with the reaction balance, the verification\nchecks with a hand calculation where one applies, and the Journal as an appendix. Nothing\nin it depends on the clock or the machine, so two runs of the same Journal produce\nbyte-identical text. `step` reports one Step instead of every solved one; `include` picks\nsections. Automatic hand references require a current static Step on an uncut 3D lattice\nbox with one fully clamped end and one single-component force on the opposite end;\nother cases explicitly report no applicable automatic reference. Formulas are `$$…$$` for KaTeX."
        return await self._call("query", QueryReportArgs(step=step, include=include).wire())

    async def query_capabilities(self) -> Any:
        "What this engine can do here: GPU presence and adapter name, thread count, engine and\nschema versions. Hosts add browser facts (cross-origin isolation, local or remote engine)."
        return await self._call("query", QueryCapabilitiesArgs().wire())
